/** 按领域实例持有的静水租约。空气和原版水会冲毁的附着物可放入，玩家改过的格子不回填。 */
public final class StillWaterLease {
    private static final String STORAGE = "xueximod_still_domain_water";

    private StillWaterLease() {
    }

    public static void fill(DomainInstance domain) {
        if (domain == null || domain.definition() == null || !domain.definition().placesStillWater()) {
            return;
        }
        ServerLevel level = domain.hostLevel();
        if (level == null) {
            return;
        }
        LeaseData data = LeaseData.get(level);
        AABB bounds = domain.geometry().bounds();
        int firstX = (int) Math.floor(bounds.minX);
        int lastX = (int) Math.ceil(bounds.maxX) - 1;
        int firstY = (int) Math.floor(bounds.minY);
        int lastY = (int) Math.ceil(bounds.maxY) - 1;
        int firstZ = (int) Math.floor(bounds.minZ);
        int lastZ = (int) Math.ceil(bounds.maxZ) - 1;
        for (int blockX = firstX; blockX <= lastX; blockX++) {
            for (int blockY = firstY; blockY <= lastY; blockY++) {
                for (int blockZ = firstZ; blockZ <= lastZ; blockZ++) {
                    if (!contained(bounds, blockX, blockY, blockZ)) {
                        continue;
                    }
                    BlockPos cell = new BlockPos(blockX, blockY, blockZ);
                    if (!level.isLoaded(cell)) {
                        data.hold(domain.instanceId(), cell, false, false);
                        continue;
                    }
                    placeIfAir(level, data, domain.instanceId(), cell);
                }
            }
        }
    }

    public static void release(DomainInstance domain) {
        if (domain == null || domain.hostLevel() == null || domain.definition() == null
                || !domain.definition().placesStillWater()) {
            return;
        }
        LeaseData.get(domain.hostLevel()).releaseOwner(domain.hostLevel(), domain.instanceId());
    }

    public static boolean liveAt(Level level, BlockPos cell) {
        if (!(level instanceof ServerLevel server) || cell == null) {
            return false;
        }
        return LeaseData.get(server).live(cell);
    }

    public static void onChunkLoad(ServerLevel level, ChunkAccess chunk) {
        if (level == null || chunk == null) {
            return;
        }
        LeaseData.get(level).reconcile(level, chunk);
    }

    private static void placeIfAir(ServerLevel level, LeaseData data, UUID ownerId, BlockPos cell) {
        BlockState state = level.getBlockState(cell);
        if (state.getBlock() == StillDomainFluids.BLOCK.get()) {
            data.hold(ownerId, cell, true, false);
            return;
        }
        boolean openAir = state.isAir() && level.getBlockEntity(cell) == null;
        if (!openAir && !washesAttachment(level, cell, state)) {
            return;
        }
        if (!openAir) {
            Block.dropResources(state, level, cell, level.getBlockEntity(cell));
        }
        level.setBlock(cell, StillDomainFluids.BLOCK.get().defaultBlockState(), 3);
        level.scheduleTick(cell, StillDomainFluids.SOURCE.get(), StillDomainFluids.SOURCE.get().getTickDelay(level));
        data.hold(ownerId, cell, true, false);
    }

    /** 与 1.20.1 {@code FlowingFluid.canHoldFluid} 的破坏集合一致，不含水方块和容器。 */
    private static boolean washesAttachment(BlockGetter reader, BlockPos cell, BlockState state) {
        if (state.isAir() || state.getBlock() == StillDomainFluids.BLOCK.get() || !state.getFluidState().isEmpty()) {
            return false;
        }
        if (state.hasBlockEntity() || reader.getBlockEntity(cell) != null) {
            return false;
        }
        if (state.getBlock() instanceof LiquidBlockContainer || state.getBlock() instanceof DoorBlock) {
            return false;
        }
        if (state.is(BlockTags.SIGNS) || state.is(Blocks.LADDER) || state.is(Blocks.SUGAR_CANE)
                || state.is(Blocks.BUBBLE_COLUMN) || state.is(Blocks.NETHER_PORTAL) || state.is(Blocks.END_PORTAL)
                || state.is(Blocks.END_GATEWAY) || state.is(Blocks.STRUCTURE_VOID)) {
            return false;
        }
        return !state.blocksMotion();
    }

    private static boolean contained(AABB bounds, int blockX, int blockY, int blockZ) {
        return blockX >= bounds.minX - 1.0E-6D && blockX + 1.0D <= bounds.maxX + 1.0E-6D
                && blockY >= bounds.minY - 1.0E-6D && blockY + 1.0D <= bounds.maxY + 1.0E-6D
                && blockZ >= bounds.minZ - 1.0E-6D && blockZ + 1.0D <= bounds.maxZ + 1.0E-6D;
    }

    static final class LeaseData extends SavedData {
        private final Map<Long, Held> cells = new HashMap<>();

        static LeaseData get(ServerLevel level) {
            return level.getDataStorage().computeIfAbsent(LeaseData::load, LeaseData::fresh, STORAGE);
        }

        static LeaseData fresh() {
            return new LeaseData();
        }

        static LeaseData load(CompoundTag tag) {
            LeaseData data = new LeaseData();
            ListTag listed = tag.getList("cells", Tag.TAG_COMPOUND);
            for (int cursor = 0; cursor < listed.size(); cursor++) {
                CompoundTag cellTag = listed.getCompound(cursor);
                Held held = new Held(cellTag.getInt("blockX"), cellTag.getInt("blockY"), cellTag.getInt("blockZ"));
                held.placed = cellTag.getBoolean("placed");
                held.pendingClear = cellTag.getBoolean("pendingClear");
                ListTag owners = cellTag.getList("owners", Tag.TAG_COMPOUND);
                for (int ownerCursor = 0; ownerCursor < owners.size(); ownerCursor++) {
                    CompoundTag ownerTag = owners.getCompound(ownerCursor);
                    if (ownerTag.hasUUID("owner")) {
                        held.owners.add(ownerTag.getUUID("owner"));
                    }
                }
                data.cells.put(held.key(), held);
            }
            return data;
        }

        @Override
        public CompoundTag save(CompoundTag tag) {
            ListTag listed = new ListTag();
            for (Held held : cells.values()) {
                CompoundTag cellTag = new CompoundTag();
                cellTag.putInt("blockX", held.blockX);
                cellTag.putInt("blockY", held.blockY);
                cellTag.putInt("blockZ", held.blockZ);
                cellTag.putBoolean("placed", held.placed);
                cellTag.putBoolean("pendingClear", held.pendingClear);
                ListTag owners = new ListTag();
                for (UUID ownerId : held.owners) {
                    CompoundTag ownerTag = new CompoundTag();
                    ownerTag.putUUID("owner", ownerId);
                    owners.add(ownerTag);
                }
                cellTag.put("owners", owners);
                listed.add(cellTag);
            }
            tag.put("cells", listed);
            return tag;
        }

        void hold(UUID ownerId, BlockPos cell, boolean placedNow, boolean clearNow) {
            Held held = cells.computeIfAbsent(cell.asLong(), ignored -> new Held(cell.getX(), cell.getY(), cell.getZ()));
            if (placedNow) {
                held.placed = true;
                held.pendingClear = false;
            }
            if (clearNow) {
                held.pendingClear = true;
                held.owners.clear();
            } else if (ownerId != null) {
                held.owners.add(ownerId);
            }
            setDirty();
        }

        boolean live(BlockPos cell) {
            Held held = cells.get(cell.asLong());
            if (held == null || held.pendingClear) {
                return false;
            }
            for (UUID ownerId : held.owners) {
                DomainInstance domain = DomainService.find(ownerId);
                if (domain != null && domain.active() && domain.definition().placesStillWater()) {
                    return true;
                }
            }
            return false;
        }

        void releaseOwner(ServerLevel level, UUID ownerId) {
            Iterator<Held> iterator = cells.values().iterator();
            while (iterator.hasNext()) {
                Held held = iterator.next();
                if (!held.owners.remove(ownerId)) {
                    continue;
                }
                if (!held.owners.isEmpty()) {
                    setDirty();
                    continue;
                }
                BlockPos cell = held.cell();
                if (!level.isLoaded(cell)) {
                    held.pendingClear = true;
                    setDirty();
                    continue;
                }
                clearIfOurs(level, cell);
                iterator.remove();
                setDirty();
            }
        }

        void reconcile(ServerLevel level, ChunkAccess chunk) {
            ChunkPos loadedChunk = chunk.getPos();
            List<LoadedEdit> edits = new ArrayList<>();
            Iterator<Held> iterator = cells.values().iterator();
            while (iterator.hasNext()) {
                Held held = iterator.next();
                if (held.blockX < loadedChunk.getMinBlockX() || held.blockX > loadedChunk.getMaxBlockX()
                        || held.blockZ < loadedChunk.getMinBlockZ() || held.blockZ > loadedChunk.getMaxBlockZ()) {
                    continue;
                }
                BlockPos cell = held.cell();
                boolean ownerLives = false;
                for (UUID ownerId : held.owners) {
                    DomainInstance domain = DomainService.find(ownerId);
                    if (domain != null && domain.active()) {
                        ownerLives = true;
                        break;
                    }
                }
                BlockState state = chunk.getBlockState(cell);
                boolean ours = state.getBlock() == StillDomainFluids.BLOCK.get();
                if (!ownerLives || held.pendingClear) {
                    if (ours) {
                        edits.add(new LoadedEdit(cell, null, true));
                    }
                    iterator.remove();
                    setDirty();
                    continue;
                }
                if (ours) {
                    held.placed = true;
                    setDirty();
                    continue;
                }
                boolean openAir = state.isAir() && chunk.getBlockEntity(cell) == null;
                if (!held.placed && (openAir || washesAttachment(chunk, cell, state))) {
                    edits.add(new LoadedEdit(cell, firstOwner(held), false));
                    continue;
                }
                iterator.remove();
                setDirty();
            }
            sweepOrphans(level, chunk, edits);
            flushLoadedEdits(level, edits);
        }

        private void sweepOrphans(ServerLevel level, ChunkAccess chunk, List<LoadedEdit> edits) {
            ChunkPos loadedChunk = chunk.getPos();
            int low = level.getMinBuildHeight();
            int high = level.getMaxBuildHeight();
            for (int blockX = loadedChunk.getMinBlockX(); blockX <= loadedChunk.getMaxBlockX(); blockX++) {
                for (int blockZ = loadedChunk.getMinBlockZ(); blockZ <= loadedChunk.getMaxBlockZ(); blockZ++) {
                    for (int blockY = low; blockY < high; blockY++) {
                        BlockPos cell = new BlockPos(blockX, blockY, blockZ);
                        BlockState state = chunk.getBlockState(cell);
                        if (state.getBlock() != StillDomainFluids.BLOCK.get()) {
                            continue;
                        }
                        if (!live(cell)) {
                            edits.add(new LoadedEdit(cell, null, true));
                            cells.remove(cell.asLong());
                            setDirty();
                        }
                    }
                }
            }
        }

        private void flushLoadedEdits(ServerLevel level, List<LoadedEdit> edits) {
            if (edits.isEmpty() || level.getServer() == null) {
                return;
            }
            List<LoadedEdit> queued = List.copyOf(edits);
            level.getServer().tell(new TickTask(level.getServer().getTickCount(), () -> {
                for (LoadedEdit edit : queued) {
                    if (!level.isLoaded(edit.cell)) {
                        continue;
                    }
                    if (edit.clearing) {
                        clearIfOurs(level, edit.cell);
                        continue;
                    }
                    placeIfAir(level, this, edit.ownerId, edit.cell);
                }
            }));
        }

        private static UUID firstOwner(Held held) {
            for (UUID ownerId : held.owners) {
                return ownerId;
            }
            return null;
        }

        private static void clearIfOurs(ServerLevel level, BlockPos cell) {
            if (level.getBlockState(cell).getBlock() == StillDomainFluids.BLOCK.get()) {
                level.setBlock(cell, Blocks.AIR.defaultBlockState(), 3);
            }
        }
    }

    private static final class LoadedEdit {
        final BlockPos cell;
        final UUID ownerId;
        final boolean clearing;

        LoadedEdit(BlockPos cell, UUID ownerId, boolean clearing) {
            this.cell = cell;
            this.ownerId = ownerId;
            this.clearing = clearing;
        }
    }

    static final class Held {
        final int blockX;
        final int blockY;
        final int blockZ;
        boolean placed;
        boolean pendingClear;
        final HashSet<UUID> owners = new HashSet<>();

        Held(int blockX, int blockY, int blockZ) {
            this.blockX = blockX;
            this.blockY = blockY;
            this.blockZ = blockZ;
        }

        long key() {
            return BlockPos.asLong(blockX, blockY, blockZ);
        }

        BlockPos cell() {
            return new BlockPos(blockX, blockY, blockZ);
        }
    }
}
"}, {"path": "src/main/java/com/bslx/XueXiMod/shu/technique/release/domain/DomainService.java", "sha256": "a70c9cd03d04d9f7954590a3232b93c2f0f89bb0fc91c14209c4939879ab9636", "content": "package com.bslx.XueXiMod.shu.technique.release.domain;

import com.bslx.XueXiMod.network.DomainSyncPacket;
import com.bslx.XueXiMod.player.MagicPool;
import com.bslx.XueXiMod.shu.balance.BalanceKeys;
import com.bslx.XueXiMod.shu.technique.release.batch.SpecialBalance;
import com.bslx.XueXiMod.player.ManaPaymentReceipt;
import com.bslx.XueXiMod.player.PlayerShuData;
import com.bslx.XueXiMod.shu.Technique;
import com.bslx.XueXiMod.shu.technique.enchant.EnchantmentSnapshot;
import com.bslx.XueXiMod.shu.technique.enchant.resource.ResourceEnchantLoad;
import com.bslx.XueXiMod.shu.technique.release.ReleaseInput;
import com.bslx.XueXiMod.shu.technique.release.bind.BoundReleasePlan;
import com.bslx.XueXiMod.shu.technique.release.bind.PublicationAttempt;
import com.bslx.XueXiMod.shu.technique.release.field.FieldZones;
import com.bslx.XueXiMod.shu.technique.release.domain.motion.DomainCastContext;
import com.bslx.XueXiMod.shu.technique.release.domain.motion.ReleaseMotionLedger;
import com.bslx.XueXiMod.shu.technique.release.domain.motion.StillWaterLease;
import com.bslx.XueXiMod.shu.technique.release.domain.motion.VolumeMotionKind;
import com.bslx.XueXiMod.shu.technique.release.domain.motion.VolumeMotionRuntime;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.phys.Vec3;

import javax.annotation.Nullable;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.UUID;

/** 同一波先预检再一起发布。到期、主人死亡、下线或跨维就整份关掉。存在期间不扣维护。 */
public final class DomainService {
    private static final ArrayList<DomainInstance> ACTIVE = new ArrayList<>();
    private static final HashSet<String> PLACED_THIS_TICK = new HashSet<>();
    private static int placedTick = Integer.MIN_VALUE;
    private static boolean legacySwept;

    private DomainService() {
    }

    public static void onServerStarted() {
        if (legacySwept) {
            return;
        }
        legacySwept = true;
        FieldZones.retireLegacyMist();
        FieldZones.retireLegacyPressure();
    }

    public static boolean tryWave(ServerPlayer player, Technique source, DomainDefinition definition, int copies, EnchantmentSnapshot snapshot) {
        return tryWave(player, source, definition, copies, snapshot, ReleaseInput.BASE);
    }

    public static boolean tryWave(ServerPlayer player, Technique source, DomainDefinition definition, int copies,
                                  EnchantmentSnapshot snapshot, ReleaseInput input) {
        return tryWave(player, source, definition, copies, snapshot, input, null, null);
    }

    /**
     * 带冻结绑定计划的开域。计划非空时必须有声明后缀，避免不同绑定在同一刻被去重合并。
     * 这里仍只收领域起手费，不收后续每轮子计划的费用。
     */
    public static boolean tryWave(ServerPlayer player, Technique source, DomainDefinition definition,
                                  int copies, EnchantmentSnapshot snapshot, ReleaseInput input,
                                  @Nullable BoundReleasePlan boundPlan, @Nullable String claimSuffix) {
        if (missingBindingSuffix(boundPlan, claimSuffix)) {
            return false;
        }
        return releaseWave(player, source, definition, copies, snapshot, null, false, claimSuffix, input, boundPlan,
                null, null, null);
    }

    /**
     * 带上这一发的附魔载荷和根施法标识。旧入口不传这两项，零接触伤的纯幽冥要走这里。
     */
    public static boolean tryWaveLoaded(ServerPlayer player, Technique source, DomainDefinition definition,
                                        int copies, EnchantmentSnapshot snapshot, ReleaseInput input,
                                        @Nullable BoundReleasePlan boundPlan, @Nullable String claimSuffix,
                                        @Nullable ResourceEnchantLoad load, @Nullable UUID rootCastId) {
        if (missingBindingSuffix(boundPlan, claimSuffix)) {
            return false;
        }
        return releaseWave(player, source, definition, copies, snapshot, null, false, claimSuffix, input, boundPlan,
                load, rootCastId, null);
    }

    public static boolean tryWaveLoaded(ServerPlayer player, Technique source, DomainDefinition definition,
                                        int copies, EnchantmentSnapshot snapshot, ReleaseInput input,
                                        @Nullable BoundReleasePlan boundPlan, @Nullable String claimSuffix,
                                        @Nullable ResourceEnchantLoad load, @Nullable UUID rootCastId,
                                        @Nullable DomainCastContext castContext) {
        if (missingBindingSuffix(boundPlan, claimSuffix)) {
            return false;
        }
        return releaseWave(player, source, definition, copies, snapshot, null, false, claimSuffix, input, boundPlan,
                load, rootCastId, castContext);
    }

    /** 费用已经由父会话预留。feet 不为空时整盒平移到接触点，不再跟施法者脚下。 */
    public static boolean tryWaveReserved(ServerPlayer player, Technique source, DomainDefinition definition, int copies,
                                          EnchantmentSnapshot snapshot, Vec3 feet, String claimSuffix) {
        return tryWaveReserved(player, source, definition, copies, snapshot, feet, claimSuffix, ReleaseInput.BASE);
    }

    public static boolean tryWaveReserved(ServerPlayer player, Technique source, DomainDefinition definition, int copies,
                                          EnchantmentSnapshot snapshot, Vec3 feet, String claimSuffix, ReleaseInput input) {
        return tryWaveReserved(player, source, definition, copies, snapshot, feet, claimSuffix, input, null);
    }

    /**
     * 费用已经由父会话预留。有冻结计划时必须带同一声明后缀。
     * 周期释放的费用不在这次开域里预扣。
     */
    public static boolean tryWaveReserved(ServerPlayer player, Technique source, DomainDefinition definition,
                                          int copies, EnchantmentSnapshot snapshot, Vec3 feet, String claimSuffix,
                                          ReleaseInput input, @Nullable BoundReleasePlan boundPlan) {
        if (missingBindingSuffix(boundPlan, claimSuffix)) {
            return false;
        }
        return releaseWave(player, source, definition, copies, snapshot, feet, true, claimSuffix, input, boundPlan,
                null, null, null);
    }

    /**
     * 费用已由父会话预留时的幽冥入口。根标识只在绑定表里已经存在时才会被持有。
     */
    public static boolean tryWaveReservedLoaded(ServerPlayer player, Technique source, DomainDefinition definition,
                                                int copies, EnchantmentSnapshot snapshot, Vec3 feet, String claimSuffix,
                                                ReleaseInput input, @Nullable BoundReleasePlan boundPlan,
                                                @Nullable ResourceEnchantLoad load, @Nullable UUID rootCastId) {
        if (missingBindingSuffix(boundPlan, claimSuffix)) {
            return false;
        }
        return releaseWave(player, source, definition, copies, snapshot, feet, true, claimSuffix, input, boundPlan,
                load, rootCastId, null);
    }

    public static boolean tryWaveReservedLoaded(ServerPlayer player, Technique source, DomainDefinition definition,
                                                int copies, EnchantmentSnapshot snapshot, Vec3 feet, String claimSuffix,
                                                ReleaseInput input, @Nullable BoundReleasePlan boundPlan,
                                                @Nullable ResourceEnchantLoad load, @Nullable UUID rootCastId,
                                                @Nullable DomainCastContext castContext) {
        if (missingBindingSuffix(boundPlan, claimSuffix)) {
            return false;
        }
        return releaseWave(player, source, definition, copies, snapshot, feet, true, claimSuffix, input, boundPlan,
                load, rootCastId, castContext);
    }

    private static boolean missingBindingSuffix(@Nullable BoundReleasePlan boundPlan, @Nullable String claimSuffix) {
        return boundPlan != null && (claimSuffix == null || claimSuffix.isEmpty());
    }

    private static boolean releaseWave(ServerPlayer player, Technique source, DomainDefinition definition, int copies,
                                       EnchantmentSnapshot snapshot, Vec3 feet, boolean reserved, String claimSuffix,
                                       ReleaseInput input, @Nullable BoundReleasePlan boundPlan,
                                       @Nullable ResourceEnchantLoad load, @Nullable UUID rootCastId,
                                       @Nullable DomainCastContext castContext) {
        if (player == null || source == null || definition == null || !(player.level() instanceof ServerLevel level)) {
            return false;
        }
        ReleaseInput frozen = input == null ? ReleaseInput.BASE : input;
        int scaledLife = frozenLife(definition, frozen);
        if (!PlayerShuData.get(player).isUnlocked(source)) {
            player.sendSystemMessage(net.minecraft.network.chat.Component.literal("§c还没有学会释放" + source.getName()));
            return false;
        }
        int count = Math.max(1, copies);
        int now = level.getServer().getTickCount();
        if (placedTick != now) {
            PLACED_THIS_TICK.clear();
            placedTick = now;
        }
        String kind = definition.nativePolicy() == null ? "plain" : definition.nativePolicy().effectKey();
        String claim = player.getUUID() + ":" + kind + ":" + definition.initialCost() + ":" + definition.lifetimeTicks();
        if (claimSuffix != null) {
            claim = claim + ":" + claimSuffix;
        }
        if (castContext != null && (definition.motionKind() != VolumeMotionKind.NONE || definition.placesStillWater())) {
            claim = claim + ":flow:" + castContext.declarationSlot() + ":" + castContext.groupId();
        }
        if (PLACED_THIS_TICK.contains(claim)) {
            return true;
        }
        int unitCost = definition.balanceId().isEmpty()
                ? definition.initialCost()
                : SpecialBalance.mana(definition.balanceId(), BalanceKeys.MANA_COST, definition.initialCost());
        Integer totalBill = exactBill(unitCost, count);
        if (totalBill == null) {
            player.sendSystemMessage(net.minecraft.network.chat.Component.literal("§c这次的份数或费用超出可表示范围，没有释放"));
            return false;
        }
        int bill = totalBill;
        if (!reserved && !MagicPool.canAfford(player, bill)) {
            player.sendSystemMessage(net.minecraft.network.chat.Component.literal("§c魔力不足"));
            return false;
        }
        List<DomainInstance> pending = new ArrayList<>();
        for (int copyOrdinal = 0; copyOrdinal < count; copyOrdinal++) {
            Vec3 targetFeet = feet;
            if (castContext != null) {
                Vec3 spatial = castContext.origin(player);
                if (!castContext.verticalAxis()) {
                    spatial = new Vec3(spatial.x, player.getY(), spatial.z);
                }
                targetFeet = spatial;
                if (castContext.scatter() && count > 1) {
                    DomainGeometry footprint = definition.place(player);
                    double ring = footprint == null ? 3.0D : Math.max(2.0D, footprint.bounds().getXsize() * 0.75D);
                    double angle = copyOrdinal * 2.399963229728653D;
                    targetFeet = new Vec3(spatial.x + Math.cos(angle) * ring, spatial.y, spatial.z + Math.sin(angle) * ring);
                }
            }
            DomainGeometry geometry = placedGeometry(definition.place(player), targetFeet, player.position(), frozen);
            if (geometry == null) {
                discard(pending);
                return false;
            }
            pending.add(new DomainInstance(player.getUUID(), level, geometry, definition, now, scaledLife, boundPlan));
        }
        if (!reserved) {
            ManaPaymentReceipt receipt = ManaPaymentReceipt.charge(player, bill, true);
            if (receipt == null) {
                discard(pending);
                return false;
            }
        }
        int placedOrdinal = 0;
        for (DomainInstance domain : pending) {
            domain.bindContact(snapshot);
            if (castContext != null) {
                domain.bindRelease(castContext.groupId(), castContext.declarationSlot());
            }
            NetherDomainCycle.attach(domain, load, rootCastId);
            ACTIVE.add(domain);
            if (domain.definition().motionKind() == VolumeMotionKind.VORTEX_HOST) {
                ReleaseMotionLedger.retain(domain);
            }
            if (domain.definition().placesStillWater()) {
                StillWaterLease.fill(domain);
            }
            if (reserved) {
                PublicationAttempt.reportPlacedCopy(placedOrdinal);
            }
            placedOrdinal++;
            DomainSyncPacket.broadcast(domain, false);
        }
        if (!reserved && bill > 0) {
            MagicPool.showBalance(player);
        }
        PLACED_THIS_TICK.add(claim);
        return true;
    }

    public static void tick(MinecraftServer server) {
        if (server == null) {
            return;
        }
        int now = server.getTickCount();
        int index = ACTIVE.size();
        while (index > 0) {
            index--;
            if (index >= ACTIVE.size()) {
                index = ACTIVE.size();
                continue;
            }
            DomainInstance domain = ACTIVE.get(index);
            int sizeBefore = ACTIVE.size();
            if (!domain.active()) {
                ACTIVE.remove(index);
            } else {
                ServerPlayer owner = server.getPlayerList().getPlayer(domain.ownerId());
                if (owner == null || !owner.isAlive() || owner.level() != domain.hostLevel() || !withinLife(now, domain.expiresAt())) {
                    closeAt(index, domain);
                }
            }
            if (ACTIVE.size() < sizeBefore) {
                index = ACTIVE.size();
            }
        }
        DomainPulses.fire(ACTIVE, now);
        List<DomainInstance> activeSnapshot = List.copyOf(ACTIVE);
        DomainBindingRuntime.tick(server, now, activeSnapshot);
        NetherDomainCycle.tick(server);
        VolumeMotionRuntime.tick(server);
    }

    public static DomainInstance find(UUID instanceId) {
        if (instanceId == null) {
            return null;
        }
        for (DomainInstance domain : ACTIVE) {
            if (instanceId.equals(domain.instanceId())) {
                return domain;
            }
        }
        return null;
    }

    public static void closeInstance(DomainInstance domain) {
        if (domain == null) {
            return;
        }
        closeAt(ACTIVE.indexOf(domain), domain);
    }

    public static void closeOwned(ServerPlayer player) {
        if (player == null) {
            return;
        }
        int index = ACTIVE.size();
        while (index > 0) {
            index--;
            if (index >= ACTIVE.size()) {
                index = ACTIVE.size();
                continue;
            }
            DomainInstance domain = ACTIVE.get(index);
            if (!player.getUUID().equals(domain.ownerId())) {
                continue;
            }
            int sizeBefore = ACTIVE.size();
            closeAt(index, domain);
            if (ACTIVE.size() < sizeBefore) {
                index = ACTIVE.size();
            }
        }
    }

    public static List<DomainInstance> active() {
        return ACTIVE;
    }

    /** 已配置单价乘份数。溢出或负数账单返回空，调用方在放置和扣款前拒绝。0 仍是 0。 */
    private static Integer exactBill(int unitCost, int copyCount) {
        if (unitCost < 0 || copyCount < 0) {
            return null;
        }
        try {
            return Math.multiplyExact(unitCost, copyCount);
        } catch (ArithmeticException overflow) {
            return null;
        }
    }

    public static int frozenLife(DomainDefinition definition, ReleaseInput input) {
        if (definition == null) {
            return 0;
        }
        ReleaseInput frozen = input == null ? ReleaseInput.BASE : input;
        return frozen.scaleDuration(definition.lifetimeTicks());
    }

    /** 先按接触点平移，再绕落地锚点放大。feet 为空时锚点就是原放置盒的地面中心。 */
    public static DomainGeometry placedGeometry(DomainGeometry placed, Vec3 feet, Vec3 playerFeet, ReleaseInput input) {
        DomainGeometry shifted = placed;
        if (placed != null && feet != null && playerFeet != null) {
            Vec3 delta = feet.subtract(playerFeet);
            shifted = new AxisBoxGeometry(placed.bounds().move(delta.x, delta.y, delta.z));
        }
        return enlarge(shifted, input);
    }

    public static DomainGeometry enlarge(DomainGeometry placed, ReleaseInput input) {
        if (placed == null) {
            return null;
        }
        ReleaseInput frozen = input == null ? ReleaseInput.BASE : input;
        return AxisBoxGeometry.scaledFromGround(placed.bounds(), frozen.sizeMultiplier());
    }

    public static boolean withinLife(int now, int expiresAt) {
        return !ReleaseInput.hasExpired(now, expiresAt);
    }

    private static void closeAt(int index, DomainInstance domain) {
        try {
            domain.close();
        } finally {
            if (index >= 0 && index < ACTIVE.size() && ACTIVE.get(index) == domain) {
                ACTIVE.remove(index);
            } else {
                ACTIVE.remove(domain);
            }
            if (domain.markRemovalBroadcast()) {
                DomainSyncPacket.broadcast(domain, true);
            }
        }
    }

    private static void discard(List<DomainInstance> pending) {
        for (DomainInstance domain : pending) {
            domain.close();
        }
    }
}
"}, {"path": "src/main/java/com/bslx/XueXiMod/shu/WaterTechniques.java", "sha256": "86da22e99528e70854a18117f8f746d251a3484e03e870ddb95b22e352e5a05f", "content": "package com.bslx.XueXiMod.shu;

import com.bslx.XueXiMod.shu.technique.TechniqueEffectRegistry;
import com.bslx.XueXiMod.shu.technique.effects.WaterFormEffect;
import com.bslx.XueXiMod.shu.technique.release.ReleaseDefinition;
import com.bslx.XueXiMod.shu.technique.release.ReleaseRegistry;
import com.bslx.XueXiMod.shu.technique.release.batch.SpecialBalance;
import com.bslx.XueXiMod.shu.technique.release.Trajectory;
import com.bslx.XueXiMod.shu.technique.release.WaterReleaseDefinition;
import com.bslx.XueXiMod.shu.technique.release.conditional.WaterPrisonEffect;
import com.bslx.XueXiMod.shu.technique.release.water.WaterBeatBridge;
import com.bslx.XueXiMod.shu.technique.release.barrier.BarrierDefinition;
import com.bslx.XueXiMod.shu.technique.release.domain.DomainDefinition;
import com.bslx.XueXiMod.shu.technique.release.guard.GuardDefinition;

/** 留下的水系成品：缺月、水幕、水雾、水环、深海重压、旋流、气泡、水牢。 */
public final class WaterTechniques {
    private static final WaterFormEffect FORM = new WaterFormEffect();

    private WaterTechniques() {
    }

    public static void register() {
        WaterBeatBridge.install();
        WaterReleaseDefinition blade = WaterReleaseDefinition.shot("water_blade", Trajectory.STRAIGHT, 10, 1.3f, 0.35f)
                .along(3.2f).span(0.7f).energy(1.35f).wetness(6)
                .swordForm();
        Technique bladeTechnique = new Technique("water_blade", "缺月", TechniqueType.SWORD, 7f, 14, 20,
                "随挥剑扫出月牙形水流弧斩，可连续衔接", 0, ShuAttribute.WATER, blade.speed());
        TechniqueManager.register(bladeTechnique);
        ReleaseRegistry.register(blade);
        TechniqueEffectRegistry.register("water_blade", FORM);
        barrier("water_curtain", "水幕", 40, 0, "身前立起一道固定的薄水墙，穿过它的箭伤害减半",
                BarrierDefinition.curtain());
        domain("water_mist", "雾雨", 80, 10, "固定的雨雾领域。完整进入的敌人出不去，并会变潮湿",
                DomainDefinition.mistRain());
        guard("water_ring", "水环", 40, 0, "环绕自身的水环，受到的伤害削去两成",
                GuardDefinition.personalRing());
        domain("water_deep_pressure", "深海重压", 80, 10, "低矮的重压领域。范围内暂时积起不流动的水，里面的人变慢、变潮湿，氧气消耗加快",
                DomainDefinition.deepPressure());
        domain("water_vortex", "水流旋涡", 80, 10, "干地水平牵引。入卷收取水势；与上升气泡和真实水组成龙卷后才按湿度扣返",
                DomainDefinition.vortex());
        domain("water_bubble_column", "气泡水柱", 60, 10, "真实水里的上升水柱。底部与旋流重合时挂上去，父旋流关闭后不再独立续挂",
                DomainDefinition.bubble());
        prison();
    }

    /**
     * 不登记水系命中效果。那条生成会打出命中体，水牢的伤害必须保持为 0。
     */
    private static void prison() {
        WaterReleaseDefinition definition = WaterReleaseDefinition.conditional("water_prison", 40, WaterPrisonEffect.INSTANCE);
        Technique technique = new Technique("water_prison", "水牢", TechniqueType.MAGIC, 0f, 400, 20,
