    public int upkeepCost() {
        return upkeepCost;
    }

    /**
     * @deprecated 领域不再按这份周期维护。返回值不是扣款节拍。
     */
    @Deprecated
    public int upkeepPeriod() {
        return upkeepPeriod;
    }

    public int lifetimeTicks() {
        if (balanceId.isEmpty()) {
            return lifetimeTicks;
