        return SpecialBalance.integer(balanceId, BalanceKeys.LIFETIME_TICKS, lifetimeTicks);
    }

    public DomainNativePolicy nativePolicy() {
        return nativePolicy;
    }

    public DomainAuraSpec auraSpec() {
