                OPEN_COST, DOMAIN_LIFE,
                new DomainNativePolicy("deep_pressure", WET_PERIOD_TICKS, 4, 10, 20, 0, 20, 0, 20,
                        SLOW_PERIOD_TICKS, 10, BREATH_MULTIPLIER_RAW).boundTo(PRESSURE_ID),
                DomainAuraSpec.tideNeutral(), true,
