                .numberParameter(BalanceKeys.EJECT_HORIZONTAL_SPEED, RawDefault.literal(0.45D),
                        BalanceBound.positiveSpeed(), BalanceUnit.BLOCKS_PER_TICK, "到顶抛出的水平速度。只在真实抛出时读取")
                .numberParameter(BalanceKeys.EJECT_VERTICAL_SPEED, RawDefault.literal(0.20D),
                        BalanceBound.positiveSpeed(), BalanceUnit.BLOCKS_PER_TICK, "到顶抛出的向上速度。只在真实抛出时读取");
        SpecialBalance.publish(builder);
    }

    private static void declareBubbleBalance() {
        SpecialBalance.publish(SpecialBalance.manaFee(
                SpecialBalance.life(
                        SpecialBalance.blocks(
                                SpecialBalance.blocks(
                                        SpecialBalance.blocks(SpecialBalance.begin(BUBBLE_ID),
                                                BalanceKeys.BOX_WIDTH, BUBBLE_WIDTH, "气泡柱宽度"),
                                        BalanceKeys.BOX_DEPTH, BUBBLE_WIDTH, "气泡柱纵深"),
                                BalanceKeys.BOX_HEIGHT, TALL_HEIGHT, "气泡柱高度"),
                        DOMAIN_LIFE, "气泡寿命。打开时读取"),
                CONTACT_MANA_COST, CONTACT_UNIT, "领域接触附魔单价")
                .numberParameter(BalanceKeys.RADIUS, RawDefault.literal(BUBBLE_RADIUS),
                        BalanceBound.positiveSize(), BalanceUnit.BLOCKS, "气泡圆柱半径。每拍读取")
                .numberParameter(BalanceKeys.RISE_SPEED, RawDefault.literal(0.12D),
                        BalanceBound.positiveSpeed(), BalanceUnit.BLOCKS_PER_TICK, "上升速度。独立水柱和挂载后的螺旋都读这份"));
    }

    private static void declareVolume(String techniqueId, double height, boolean momentum, boolean slow, boolean breath) {
        com.bslx.XueXiMod.shu.balance.TechniqueBalanceSpec.Builder builder = SpecialBalance.manaFee(
                SpecialBalance.life(
                        SpecialBalance.blocks(
                                SpecialBalance.blocks(
                                        SpecialBalance.blocks(SpecialBalance.begin(techniqueId),
                                                BalanceKeys.BOX_WIDTH, SHARED_WIDTH, "领域宽度"),
                                        BalanceKeys.BOX_DEPTH, SHARED_DEPTH, "领域纵深"),
                                BalanceKeys.BOX_HEIGHT, height, "领域高度"),
                        DOMAIN_LIFE, "领域寿命"),
                CONTACT_MANA_COST, CONTACT_UNIT, "领域接触附魔单价");
        if (momentum || slow || breath) {
            builder = SpecialBalance.ticks(builder, WET_PERIOD, WET_PERIOD_TICKS, "领域潮湿周期");
        }
        if (momentum) {
            builder = SpecialBalance.ticks(builder, MOMENTUM_PERIOD, MOMENTUM_PERIOD_TICKS, "领域水势周期");
        }
        if (slow) {
            builder = SpecialBalance.ticks(builder, SLOW_PERIOD, SLOW_PERIOD_TICKS, "领域减速周期");
        }
        if (breath) {
            builder = builder.numberParameter(BREATH_MULTIPLIER, RawDefault.literal(BREATH_MULTIPLIER_RAW),
                    BalanceBound.multiplier(), BalanceUnit.MULTIPLIER, "深压耗氧倍率");
        }
        SpecialBalance.publish(builder);
    }
}
"}, {"path": "src/main/java/com/bslx/XueXiMod/shu/technique/release/domain/motion/DomainCastContext.java", "sha256": "45f88a099c4c54560d5189356c6a03d40040e684b118ff4f226a128af793ac7d", "content": "package com.bslx.XueXiMod.shu.technique.release.domain.motion;

import com.bslx.XueXiMod.shu.technique.release.ReleaseBatch;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.phys.Vec3;

import javax.annotation.Nullable;
import java.util.UUID;

/**
 * 一次领域成员的空间结果。接触点优先于空间落点，空间落点优先于脚底。
 * 锁定实体不改生成点。垂落不把竖轴体积放倒。
 */
public final class DomainCastContext {
    private final UUID groupId;
    private final int declarationSlot;
    private final boolean spaceLock;
    private final boolean scatter;
    private final boolean entityLock;
    private final boolean dropPath;
    private final boolean explicitContact;
    private final @Nullable Vec3 contactPoint;

    public DomainCastContext(UUID groupId, int declarationSlot, boolean spaceLock, boolean scatter,
                             boolean entityLock, boolean dropPath, boolean explicitContact,
                             @Nullable Vec3 contactPoint) {
        this.groupId = groupId == null ? new UUID(0L, declarationSlot) : groupId;
        this.declarationSlot = declarationSlot;
        this.spaceLock = spaceLock;
        this.scatter = scatter;
        this.entityLock = entityLock;
        this.dropPath = dropPath;
        this.explicitContact = explicitContact;
        this.contactPoint = contactPoint;
    }

    public UUID groupId() {
        return groupId;
    }

    public int declarationSlot() {
        return declarationSlot;
    }

    public boolean scatter() {
        return scatter;
    }

    /** 竖轴体积始终直立。垂落标记只说明这次没有把柱体放倒。 */
    public boolean verticalAxis() {
        return !dropPath || dropPath;
    }

    public Vec3 origin(ServerPlayer player) {
        if (explicitContact && contactPoint != null) {
            return contactPoint;
        }
        if (entityLock && !spaceLock) {
            if (contactPoint != null) {
                return contactPoint;
            }
            return player.position();
        }
        if (spaceLock) {
            return ReleaseBatch.sharedLanding(player, true);
        }
        if (contactPoint != null) {
            return contactPoint;
        }
        return player.position();
    }
}
"}, {"path": "src/main/java/com/bslx/XueXiMod/shu/technique/release/domain/motion/ReleaseMotionLedger.java", "sha256": "559046938ac428165df7a0f485d24cf20f5020214e29f5758bec37fe1f6ed3cc", "content": "package com.bslx.XueXiMod.shu.technique.release.domain.motion;

import com.bslx.XueXiMod.shu.technique.release.domain.DomainInstance;
import com.bslx.XueXiMod.shu.technique.release.domain.DomainService;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.UUID;

/** 同一释放组、同一声明下的分体共用入卷、偏转、抛出和控权。组结束后丢掉，不留世界级黑名单。 */
public final class ReleaseMotionLedger {
    private static final Map<String, ReleaseMotionLedger> OPEN = new HashMap<>();

    private final Set<UUID> settled = new HashSet<>();
    private final Set<UUID> deflected = new HashSet<>();
    private final Set<UUID> ejected = new HashSet<>();
    private final Map<UUID, UUID> controlledBy = new HashMap<>();
    private final Map<UUID, Set<UUID>> rootsByInstance = new HashMap<>();
    private final Map<UUID, Double> seatAngle = new HashMap<>();
    private final Map<UUID, Double> seatRing = new HashMap<>();

    private ReleaseMotionLedger() {
    }

    public static void retain(DomainInstance domain) {
        if (domain == null || domain.releaseGroup() == null || domain.declarationSlot() < 0) {
            return;
        }
        OPEN.computeIfAbsent(key(domain), ignored -> new ReleaseMotionLedger());
    }

    public static ReleaseMotionLedger find(DomainInstance domain) {
        if (domain == null || domain.releaseGroup() == null || domain.declarationSlot() < 0) {
            return null;
        }
        return OPEN.get(key(domain));
    }

    public static void dropIfIdle(DomainInstance domain) {
        if (domain == null || domain.releaseGroup() == null || domain.declarationSlot() < 0) {
            return;
        }
        String ledgerKey = key(domain);
        for (DomainInstance active : DomainService.active()) {
            if (active != domain && active.active() && ledgerKey.equals(key(active))) {
                return;
            }
        }
        ReleaseMotionLedger ledger = OPEN.remove(ledgerKey);
        if (ledger != null) {
            ledger.controlledBy.clear();
            ledger.rootsByInstance.clear();
            ledger.seatAngle.clear();
            ledger.seatRing.clear();
        }
    }

    private static String key(DomainInstance domain) {
        return domain.releaseGroup() + ":" + domain.declarationSlot();
    }

    public boolean settled(UUID entityId) {
        return entityId != null && settled.contains(entityId);
    }

    public void markSettled(UUID entityId) {
        if (entityId != null) {
            settled.add(entityId);
        }
    }

    public boolean deflected(UUID projectileId) {
        return projectileId != null && deflected.contains(projectileId);
    }

    public void markDeflected(UUID projectileId) {
        if (projectileId != null) {
            deflected.add(projectileId);
        }
    }

    public boolean ejected(UUID entityId) {
        return entityId != null && ejected.contains(entityId);
    }

    public void markEjected(UUID entityId) {
        if (entityId != null) {
            ejected.add(entityId);
            controlledBy.remove(entityId);
            forgetRoot(entityId);
        }
    }

    public boolean controlledByOther(UUID entityId, UUID instanceId) {
        UUID holder = controlledBy.get(entityId);
        return holder != null && !holder.equals(instanceId);
    }

    public boolean controls(UUID instanceId, UUID entityId) {
        return instanceId != null && instanceId.equals(controlledBy.get(entityId));
    }

    public void claim(UUID instanceId, UUID entityId) {
        if (instanceId != null && entityId != null) {
            controlledBy.put(entityId, instanceId);
        }
    }

    public void claimRoot(UUID instanceId, UUID rootId) {
        if (instanceId != null && rootId != null) {
            rootsByInstance.computeIfAbsent(instanceId, ignored -> new HashSet<>()).add(rootId);
        }
    }

    public List<UUID> roots(UUID instanceId) {
        ArrayList<UUID> listed = new ArrayList<>();
        Set<UUID> stored = instanceId == null ? null : rootsByInstance.get(instanceId);
        if (stored != null) {
            listed.addAll(stored);
        }
        listed.sort(Comparator.naturalOrder());
        return listed;
    }

    public double seatAngle(UUID entityId) {
        Double stored = entityId == null ? null : seatAngle.get(entityId);
        return stored == null ? Double.NaN : stored;
    }

    public double seatRing(UUID entityId) {
        Double stored = entityId == null ? null : seatRing.get(entityId);
        return stored == null ? Double.NaN : stored;
    }

    public void assignSeat(UUID entityId, double angle, double ring) {
        if (entityId != null && Double.isFinite(angle) && Double.isFinite(ring)) {
            seatAngle.put(entityId, angle);
            seatRing.put(entityId, ring);
        }
    }

    public void releaseControl(UUID entityId) {
        if (entityId != null) {
            controlledBy.remove(entityId);
            forgetRoot(entityId);
        }
    }

    public void releaseInstance(UUID instanceId) {
        if (instanceId == null) {
            return;
        }
        controlledBy.entrySet().removeIf(entry -> instanceId.equals(entry.getValue()));
        Set<UUID> stored = rootsByInstance.remove(instanceId);
        if (stored != null) {
            for (UUID entityId : stored) {
                seatAngle.remove(entityId);
                seatRing.remove(entityId);
            }
        }
    }

    private void forgetRoot(UUID entityId) {
        seatAngle.remove(entityId);
        seatRing.remove(entityId);
        for (Set<UUID> stored : rootsByInstance.values()) {
            stored.remove(entityId);
        }
    }

    public boolean holdsAny(UUID instanceId) {
        return instanceId != null && controlledBy.containsValue(instanceId);
    }

    public Set<UUID> heldBy(UUID instanceId) {
        HashSet<UUID> held = new HashSet<>();
        if (instanceId == null) {
            return held;
        }
        for (Map.Entry<UUID, UUID> entry : controlledBy.entrySet()) {
            if (instanceId.equals(entry.getValue())) {
                held.add(entry.getKey());
            }
        }
        return held;
    }
}
"}, {"path": "src/main/java/com/bslx/XueXiMod/shu/technique/release/momentum/WaterMomentum.java", "sha256": "9845fab00f685c2439190004cfb81cce2be6aa9009e2898d29c055ba9c9d7a03", "content": "package com.bslx.XueXiMod.shu.technique.release.momentum;

import com.bslx.XueXiMod.network.ModNetwork;
import com.bslx.XueXiMod.network.WaterMomentumNotice;
import com.bslx.XueXiMod.player.PlayerShuData;
import net.minecraft.server.level.ServerPlayer;

import java.util.ArrayList;
import java.util.Iterator;
import java.util.UUID;

/**
 * 水势账。和魔力分开，0 到 100。
 * 可用额是余额减去还没提交的预留。同一笔只能提交一次，取消不退已提交的。
 */
public final class WaterMomentum {
    public static final float UPPER_BOUND = 100f;

    private static final ArrayList<Hold> HOLDS = new ArrayList<>();

    private WaterMomentum() {
    }

    public static float available(ServerPlayer player) {
        if (player == null) {
            return 0f;
        }
        float reserved = 0f;
        UUID playerId = player.getUUID();
        for (Hold hold : HOLDS) {
            if (hold.state == Hold.State.RESERVED && hold.playerId.equals(playerId)) {
                reserved += hold.amount;
            }
        }
        float remaining = PlayerShuData.get(player).getWaterMomentum() - reserved;
        if (!Float.isFinite(remaining) || remaining <= 0f) {
            return 0f;
        }
        return remaining;
    }

    public static Hold reserve(ServerPlayer player, float amount) {
        float requested = amount > 0f && Float.isFinite(amount) ? amount : 0f;
        Hold hold = new Hold(player.getUUID(), requested);
        if (requested <= 0f) {
            hold.state = Hold.State.COMMITTED;
            return hold;
        }
        if (requested > available(player) + 0.001f) {
            hold.state = Hold.State.REJECTED;
            return hold;
        }
        hold.state = Hold.State.RESERVED;
        HOLDS.add(hold);
        return hold;
    }

    public static void commit(ServerPlayer player, Hold hold) {
        if (hold == null || player == null || hold.state != Hold.State.RESERVED) {
            return;
        }
        if (!hold.playerId.equals(player.getUUID())) {
            return;
        }
        hold.state = Hold.State.COMMITTED;
        HOLDS.remove(hold);
        if (hold.amount <= 0f) {
            return;
        }
        store(player, PlayerShuData.get(player).getWaterMomentum() - hold.amount);
    }

    /**
     * 只有这笔仍是该玩家的 RESERVED 并真正扣到余额时返回真。
     * 现有 {@link #commit} 不改返回值，避免旧调用方把“没扣成”当成成功。
     */
    public static boolean commitReserved(ServerPlayer player, Hold hold) {
        if (hold == null || player == null || hold.state != Hold.State.RESERVED) {
            return false;
        }
        if (!hold.playerId.equals(player.getUUID())) {
            return false;
        }
        hold.state = Hold.State.COMMITTED;
        HOLDS.remove(hold);
        if (hold.amount > 0f) {
            store(player, PlayerShuData.get(player).getWaterMomentum() - hold.amount);
        }
        return true;
    }

    public static void release(Hold hold) {
        if (hold == null || hold.state != Hold.State.RESERVED) {
            return;
        }
        hold.state = Hold.State.RELEASED;
        HOLDS.remove(hold);
    }

    public static void releaseAll(UUID playerId) {
        if (playerId == null) {
            return;
        }
        Iterator<Hold> iterator = HOLDS.iterator();
        while (iterator.hasNext()) {
            Hold hold = iterator.next();
            if (hold.playerId.equals(playerId) && hold.state == Hold.State.RESERVED) {
                hold.state = Hold.State.RELEASED;
                iterator.remove();
            }
        }
    }

    /**
     * 同一笔里先扣再返，只写一次余额，只通知一次。
     * 正费用必须严格不大于可用额，不用 0.001 容差把零余额收成免费。
     * 中间不会先写成 0。上限仍由玩家数据夹到 100。
     */
    public static Settlement settle(ServerPlayer player, float charge, float refund) {
        if (player == null) {
            return new Settlement(false, 0F);
        }
        float safeCharge = Float.isFinite(charge) && charge > 0F ? charge : 0F;
        float safeRefund = Float.isFinite(refund) && refund > 0F ? refund : 0F;
        float stored = PlayerShuData.get(player).getWaterMomentum();
        if (safeCharge > 0F && !(available(player) >= safeCharge)) {
            return new Settlement(false, stored);
        }
        storeSettled(player, stored - safeCharge + safeRefund);
        return new Settlement(true, PlayerShuData.get(player).getWaterMomentum());
    }

    /** 实际打出或实际受到的伤害。超出 100 的部分丢掉。 */
    public static void credit(ServerPlayer player, float amount) {
        if (player == null || amount <= 0f || !Float.isFinite(amount)) {
            return;
        }
        store(player, PlayerShuData.get(player).getWaterMomentum() + amount);
    }

    /** 写入后按实际差额通知客户端。顶到 0 或 100 时只显示真正变化的那一段。 */
    private static void store(ServerPlayer player, float next) {
        PlayerShuData data = PlayerShuData.get(player);
        float before = data.getWaterMomentum();
        data.setWaterMomentum(next);
        float after = data.getWaterMomentum();
        PlayerShuData.save(player, data);
        float change = after - before;
        if (change > 0.05f || change < -0.05f) {
            ModNetwork.sendToPlayer(player, new WaterMomentumNotice(change, after));
        }
    }

    /** 入卷和偏转的最终差额即使小于 0.05 也通知一次。 */
    private static void storeSettled(ServerPlayer player, float next) {
        PlayerShuData data = PlayerShuData.get(player);
        float before = data.getWaterMomentum();
        data.setWaterMomentum(next);
        float after = data.getWaterMomentum();
        PlayerShuData.save(player, data);
        if (Float.compare(before, after) != 0) {
            ModNetwork.sendToPlayer(player, new WaterMomentumNotice(after - before, after));
        }
    }

    /** 只记本模组这次拦截真正减掉的伤害，不把别的模组的减伤再记一遍。 */
    public static void creditMitigated(ServerPlayer player, float reduced) {
        credit(player, reduced);
    }

    public static final class Settlement {
        private final boolean paid;
        private final float after;

        Settlement(boolean paid, float after) {
            this.paid = paid;
            this.after = after;
        }

        public boolean paid() {
            return paid;
        }

        public float after() {
            return after;
        }
    }

    public static final class Hold {
        public enum State {
            RESERVED,
            COMMITTED,
            RELEASED,
            REJECTED
        }

        final UUID playerId;
        final float amount;
        State state = State.REJECTED;

        Hold(UUID playerId, float amount) {
            this.playerId = playerId;
            this.amount = amount;
        }

        public boolean accepted() {
            return this.state == State.RESERVED || this.state == State.COMMITTED;
        }

        public boolean reserved() {
            return this.state == State.RESERVED;
        }
    }
}
"}, {"path": "src/main/java/com/bslx/XueXiMod/block/StillDomainFluids.java", "sha256": "d242e098c31d490058783e4c80bcb5202a0503dc46385cf3dfaeff7379f70ad7", "content": "package com.bslx.XueXiMod.block;

import com.bslx.XueXiMod.XueXiMod;
import net.minecraft.sounds.SoundEvents;
import net.minecraft.util.Mth;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.Items;
import net.minecraft.world.level.ClipContext;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.block.LiquidBlock;
import net.minecraft.world.level.block.state.BlockBehaviour;
import net.minecraft.world.level.material.Fluid;
import net.minecraft.world.level.pathfinder.BlockPathTypes;
import net.minecraft.world.phys.BlockHitResult;
import net.minecraft.world.phys.HitResult;
import net.minecraft.world.phys.Vec3;
import net.minecraftforge.event.entity.player.PlayerInteractEvent;
import net.minecraftforge.eventbus.api.IEventBus;
import net.minecraftforge.eventbus.api.SubscribeEvent;
import net.minecraftforge.client.extensions.common.IClientFluidTypeExtensions;
import net.minecraftforge.fluids.FluidType;
import net.minecraftforge.fluids.ForgeFlowingFluid;
import net.minecraftforge.fml.common.Mod;
import net.minecraftforge.registries.DeferredRegister;
import net.minecraftforge.registries.ForgeRegistries;
import net.minecraftforge.registries.RegistryObject;

import java.util.function.Consumer;

/** 深海领域的临时静水。不注册方块物品，避免被拿去无限复制。 */
@Mod.EventBusSubscriber(modid = XueXiMod.MOD_ID)
public final class StillDomainFluids {
    public static final DeferredRegister<FluidType> TYPES =
            DeferredRegister.create(ForgeRegistries.Keys.FLUID_TYPES, XueXiMod.MOD_ID);
    public static final DeferredRegister<Fluid> FLUIDS =
            DeferredRegister.create(ForgeRegistries.FLUIDS, XueXiMod.MOD_ID);

    public static final RegistryObject<FluidType> TYPE = TYPES.register("still_domain_water", StillDomainFluids::createType);
    public static final RegistryObject<StillDomainFluid.Source> SOURCE = FLUIDS.register("still_domain_water",
            StillDomainFluids::createSource);
    public static final RegistryObject<StillDomainFluid.Flowing> FLOWING = FLUIDS.register("still_domain_water_flowing",
            StillDomainFluids::createFlowing);
    public static final RegistryObject<LiquidBlock> BLOCK = ModBlocks.BLOCKS.register("still_domain_water",
            () -> new LiquidBlock(SOURCE, BlockBehaviour.Properties.copy(Blocks.WATER).noLootTable()));
    private static final ForgeFlowingFluid.Properties PROPERTIES = new ForgeFlowingFluid.Properties(TYPE, SOURCE, FLOWING)
            .block(BLOCK)
            .slopeFindDistance(1)
            .levelDecreasePerBlock(8)
            .explosionResistance(100.0F)
            .tickRate(40);

    private StillDomainFluids() {
    }

    public static void register(IEventBus eventBus) {
        TYPES.register(eventBus);
        FLUIDS.register(eventBus);
    }

    private static StillDomainFluid.Source createSource() {
        return new StillDomainFluid.Source(PROPERTIES);
    }

    private static StillDomainFluid.Flowing createFlowing() {
        return new StillDomainFluid.Flowing(PROPERTIES);
    }

    private static FluidType createType() {
        return new FluidType(FluidType.Properties.create()
                .descriptionId("block.xueximod.still_domain_water")
                .canSwim(true)
                .canDrown(true)
                .canExtinguish(true)
                .canHydrate(true)
                .supportsBoating(true)
                .canPushEntity(true)
                .canConvertToSource(false)
                .motionScale(0.014D)
                .fallDistanceModifier(0.0F)
                .density(1000)
                .viscosity(1000)
                .temperature(300)
                .pathType(BlockPathTypes.WATER)
                .adjacentPathType(null)
                .sound(net.minecraftforge.common.SoundActions.BUCKET_FILL, SoundEvents.BUCKET_FILL)
                .sound(net.minecraftforge.common.SoundActions.BUCKET_EMPTY, SoundEvents.BUCKET_EMPTY)) {
            @Override
            public void initializeClient(Consumer<IClientFluidTypeExtensions> consumer) {
                com.bslx.XueXiMod.client.StillDomainWaterClient.attach(consumer);
            }
        };
    }

    @SubscribeEvent
    public static void onBlockUse(PlayerInteractEvent.RightClickBlock event) {
        refuseContainer(event.getItemStack().getItem() == Items.BUCKET || event.getItemStack().getItem() == Items.GLASS_BOTTLE,
                event.getLevel().getFluidState(event.getPos()).getType() instanceof StillDomainFluid, event);
    }

    @SubscribeEvent
    public static void onItemUse(PlayerInteractEvent.RightClickItem event) {
        if (event.getEntity() == null || event.getLevel() == null) {
            return;
        }
        boolean container = event.getItemStack().getItem() == Items.BUCKET
                || event.getItemStack().getItem() == Items.GLASS_BOTTLE;
        if (!container) {
            return;
        }
        BlockHitResult trace = sourceTrace(event.getEntity());
        boolean ours = trace.getType() == HitResult.Type.BLOCK
                && event.getLevel().getFluidState(trace.getBlockPos()).getType() instanceof StillDomainFluid;
        refuseContainer(true, ours, event);
    }

    private static BlockHitResult sourceTrace(Player player) {
        float pitch = player.getXRot();
        float yaw = player.getYRot();
        Vec3 eye = player.getEyePosition();
        float yawCosine = Mth.cos(-yaw * ((float) Math.PI / 180F) - (float) Math.PI);
        float yawSine = Mth.sin(-yaw * ((float) Math.PI / 180F) - (float) Math.PI);
        float pitchCosine = -Mth.cos(-pitch * ((float) Math.PI / 180F));
        float pitchSine = Mth.sin(-pitch * ((float) Math.PI / 180F));
        double reach = player.getBlockReach();
        Vec3 far = eye.add(yawSine * pitchCosine * reach, pitchSine * reach, yawCosine * pitchCosine * reach);
        return player.level().clip(new ClipContext(eye, far, ClipContext.Block.OUTLINE, ClipContext.Fluid.SOURCE_ONLY, player));
    }

    private static void refuseContainer(boolean container, boolean ourFluid, PlayerInteractEvent event) {
        if (!container || !ourFluid) {
            return;
        }
        event.setCanceled(true);
        event.setCancellationResult(net.minecraft.world.InteractionResult.FAIL);
    }
