    /** 马上提交。蓄力宿主在这里直接拒绝，不排进以后的 tick。 */
    static ReleaseOutcome commitNow(ServerPlayer player, Technique action, List<Technique> techniques,
                                     int actionIndex, ItemStack weapon, float finalDamage, boolean carries,
