    static boolean playAction(ServerPlayer player, Technique action, List<Technique> techniques, int actionIndex,
                              ItemStack weapon, ActionWindow.Sink sink, ReleaseInput chainInput, CastPlanContext planContext) {
        if (player == null || !player.isAlive() || sink == null || TechniqueEffectRegistry.get(action.getId()) == null) {
            return false;
        }
        runSegment(player, action, techniques, actionIndex, weapon, 0f, false, EnchantmentResolution.empty(),
                null, false, false, null, 0, 1, null, player.getLookAngle(), player.position(),
                EnchantBonus.NONE, 0, null, null, sink, chainInput, planContext);
        return true;
    }

    /** 条件释放的真实回执。排进调度器本身不算提交。 */
    static ReleaseOutcome commitConditional(ServerPlayer player, ReleaseDefinition definition,
                                            UUID operationId, EnchantmentSnapshot contact) {
        return commitConditional(player, definition, operationId, contact, ReleaseInput.BASE);
    }

    static ReleaseOutcome commitConditional(ServerPlayer player, ReleaseDefinition definition,
                                            UUID operationId, EnchantmentSnapshot contact, ReleaseInput chainInput) {
        return commitConditional(player, definition, operationId, contact, chainInput, null);
    }

    static ReleaseOutcome commitConditional(ServerPlayer player, ReleaseDefinition definition,
                                            UUID operationId, EnchantmentSnapshot contact, ReleaseInput chainInput,
                                            ManaPaymentReceipt receipt) {
        int nowTick = player == null || player.getServer() == null ? 0 : player.getServer().getTickCount();
        if (player == null || !player.isAlive()) {
            return ReleaseOutcome.cancelled(nowTick, "施法者已经离开");
        }
        if (definition == null || definition.conditionalEffect() == null || operationId == null) {
            return ReleaseOutcome.rejected(nowTick, "没有条件释放");
        }
        try {
            ReleaseInput frozenInput = chainInput == null ? ReleaseInput.BASE : chainInput;
            ConditionalResult result = definition.conditionalEffect().attempt(player, operationId, contact, frozenInput, receipt);
            if (result != null && result.isCommitted()) {
                return ReleaseOutcome.committed(nowTick);
            }
            String because = result == null || result.reason() == null ? "" : result.reason();
            return ReleaseOutcome.rejected(nowTick, because);
        } catch (RuntimeException failure) {
            DebugLog.log("条件释放失败：" + failure);
            return ReleaseOutcome.rejected(nowTick, "这次没有释放");
        }
    }

    static void runSegment(ServerPlayer player, Technique action, List<Technique> techniques, int actionIndex,
                            ItemStack weapon, float finalDamage, boolean carries,
                            EnchantmentResolution enchantments, Consumer<Vec3> onFirstTrigger,
                            boolean lockThisCast, boolean dropThisCast,
                            ReleaseBatch.Tally tally, int copyIndex, int copyCount,
                            ReleaseBatch batch, Vec3 lookVec, Vec3 position,
                            EnchantBonus bonus, int volley,
                            Vec3 contactOrigin, Vec3 contactLook, ActionWindow.Sink actionSink, ReleaseInput chainInput) {
        runSegment(player, action, techniques, actionIndex, weapon, finalDamage, carries, enchantments,
                onFirstTrigger, lockThisCast, dropThisCast, tally, copyIndex, copyCount, batch, lookVec, position,
                bonus, volley, contactOrigin, contactLook, actionSink, chainInput, null);
    }

    static void runSegment(ServerPlayer player, Technique action, List<Technique> techniques, int actionIndex,
                            ItemStack weapon, float finalDamage, boolean carries,
                            EnchantmentResolution enchantments, Consumer<Vec3> onFirstTrigger,
                            boolean lockThisCast, boolean dropThisCast,
                            ReleaseBatch.Tally tally, int copyIndex, int copyCount,
                            ReleaseBatch batch, Vec3 lookVec, Vec3 position,
                            EnchantBonus bonus, int volley,
                            Vec3 contactOrigin, Vec3 contactLook, ActionWindow.Sink actionSink, ReleaseInput chainInput,
                            CastPlanContext planContext) {
        long segmentStart = PerformanceRecorder.begin();
        try {
        ReleaseInput frozenInput = chainInput == null ? ReleaseInput.BASE : chainInput;
        ReleaseDefinition conditionalDefinition = ReleaseRegistry.get(action.getId());
        if (action.getBaseDamage() <= 0f && conditionalDefinition != null && conditionalDefinition.conditionalEffect() != null) {
            return;
        }
        if (contactOrigin != null) {
            position = contactOrigin;
        }
        if (contactLook != null && contactLook.lengthSqr() > 1.0E-8) {
            lookVec = contactLook.normalize();
        }
        final Vec3 scheduledLook = lookVec;
        final Vec3 scheduledPosition = position;
        TechniqueEffect effect = TechniqueEffectRegistry.get(action.getId());
        if (effect == null) {
            return;
        }
        ReleaseDefinition attackDefinition = ReleaseRegistry.get(action.getId());
        int chargeTicks = attackDefinition == null ? 0 : attackDefinition.chargeTicks();
        if (chargeTicks > 0 && !ChargeGate.armed(player.getUUID()) && !Boolean.TRUE.equals(chargeReady.get())) {
            ReleaseExecutionContext scheduledContext = domainContext();
            if (scheduledContext != null) {
                LifetimeToken scheduledToken = scheduledContext.token();
                WaterMomentum.Hold momentumHold = WaterMomentum.reserve(player, attackDefinition.momentumSpend());
                MinecraftServer automaticServer = player.getServer();
                if (automaticServer == null) {
                    WaterMomentum.release(momentumHold);
                    return;
                }
                ChainScheduler.schedule(automaticServer, automaticServer.getTickCount() + chargeTicks, () -> {
                    int firedTick = automaticServer.getTickCount();
                    if (!player.isAlive() || scheduledToken == null || !scheduledToken.valid(firedTick)) {
                        WaterMomentum.release(momentumHold);
                        return;
                    }
                    ReleaseExecutionContext.bind(scheduledContext);
                    chargeReady.set(Boolean.TRUE);
                    try {
                        WaterMomentum.commit(player, momentumHold);
                        runSegment(player, action, techniques, actionIndex, weapon, finalDamage, carries, enchantments,
                                onFirstTrigger, lockThisCast, dropThisCast, tally, copyIndex, copyCount, batch, scheduledLook,
                                scheduledPosition, bonus, volley, contactOrigin, contactLook, actionSink, frozenInput, planContext);
                    } finally {
                        chargeReady.set(Boolean.FALSE);
                        ReleaseExecutionContext.unbind();
                    }
                });
                return;
            }
            int epoch = ChargeGate.epoch(player.getUUID());
            WaterMomentum.Hold hold = WaterMomentum.reserve(player, attackDefinition.momentumSpend());
            MinecraftServer server = player.getServer();
            if (server == null) {
                WaterMomentum.release(hold);
                return;
            }
            ChainScheduler.schedule(server, server.getTickCount() + chargeTicks, () -> {
                if (!ChargeGate.same(player.getUUID(), epoch) || !player.isAlive()) {
                    WaterMomentum.release(hold);
                    return;
                }
                WaterMomentum.commit(player, hold);
                ChargeGate.arm(player.getUUID());
                try {
                    runSegment(player, action, techniques, actionIndex, weapon, finalDamage, carries, enchantments,
                            onFirstTrigger, lockThisCast, dropThisCast, tally, copyIndex, copyCount, batch, scheduledLook,
                            scheduledPosition, bonus, volley, contactOrigin, contactLook, actionSink, frozenInput, planContext);
                } finally {
                    ChargeGate.disarm(player.getUUID());
                }
            });
            return;
        }
        if (chargeTicks <= 0 && attackDefinition != null) {
            WaterMomentum.commit(player, WaterMomentum.reserve(player, attackDefinition.momentumSpend()));
        }
        HeavyWater.Session heavySession = null;
        HostGroupContext openedGroup = HostGroupContext.current();
        ReleaseBatch outer = ReleaseBatch.current();
        boolean geometryOnly = batch != null
                && tally == null
                && contactOrigin == null
                && com.bslx.XueXiMod.shu.technique.release.batch.BirthLayout.current() != null;
        ReleaseBatch selectionBatch = batch;
        ReleaseBatch settlementBatch = geometryOnly ? null : batch;
        if (attackDefinition != null && attackDefinition.heavyMomentumPerCopy() > 0f) {
            int multiplier = openedGroup == null ? SkillEntityCount.entityCount() : openedGroup.spawnCount();
            int plannedCopies = Math.max(1, copyCount) * multiplier;
            String groupKey = openedGroup == null
                    ? player.getUUID() + "/" + action.getId() + "/" + volley + "/"
                    + System.identityHashCode(settlementBatch) + "/" + player.serverLevel().getGameTime()
                    : player.getUUID() + "/host/" + openedGroup.groupId();
            heavySession = HeavyWater.enter(player, groupKey, attackDefinition.heavyMomentumPerCopy(), plannedCopies);
        }
        if (settlementBatch != null) {
            ReleaseBatch.bind(settlementBatch);
        }
        try {
            EnchantmentResolution applied = carries ? enchantments : EnchantmentResolution.empty();
            RoleScan roleScan = resolveRoles(techniques, actionIndex, planContext);
            boolean spaceLock = roleScan.spaceLock;
            boolean entityLock = roleScan.entityLock;
            boolean scatter = roleScan.scatter;
            boolean tracking = roleScan.tracking;
            Trajectory pathOverride = roleScan.pathOverride;
            boolean chainLock = entityLock;
            Trajectory chainPath = pathOverride;
            boolean chainTracking = tracking;
            FieldInfluence influence = FieldZones.influence(player);
            float usedDamage = finalDamage * influence.damageScale();
            tracking |= influence.attachedTracking;
            if (!entityLock && influence.attachedLock) {
                entityLock = true;
            }
            if (pathOverride == null && influence.attachedPath != null) {
                pathOverride = influence.attachedPath;
            }
            HostGroupContext hostGroup = HostGroupContext.current();
            boolean useFrozen = hostGroup != null && hostGroup.hasFrozenLook();
            ReleaseExecutionContext automaticContext = domainContext();
            boolean domainAutomatic = automaticContext != null;
            LivingEntity lockedTarget = null;
            if (useFrozen) {
                lookVec = hostGroup.frozenLook();
            } else if (domainAutomatic) {
                lockedTarget = automaticContext.targetCheck().stillValid(automaticContext.localTargetId());
                if (lockedTarget == null) {
                    lookVec = automaticContext.baseDirection();
                }
            } else if (entityLock) {
                lockedTarget = LockTargetService.resolve(player);
                if (lockedTarget != null) {
                    lockedTarget.addEffect(new MobEffectInstance(MobEffects.GLOWING, 200, 0));
                }
            }
            if (attackDefinition != null && attackDefinition.fieldRadius() > 0f) {
                FieldSpawner.releaseAttached(player, attackDefinition, 1, chainLock, chainPath, chainTracking, frozenInput);
            }
            boolean mutable = attackDefinition != null && attackDefinition.trajectoryMutable();
            boolean dedicatedAim = attackDefinition != null && attackDefinition.dedicatedInitialAim();
            boolean frameLock = entityLock && mutable ? true : lockThisCast;
            if (spaceLock) {
                frameLock = entityLock && mutable;
            }
            if (dedicatedAim) {
                frameLock = false;
                if (!useFrozen && entityLock && lockedTarget != null) {
                    Vec3 fromPoint = domainAutomatic
                            ? automaticContext.origin()
                            : (contactOrigin != null ? contactOrigin : player.getEyePosition());
                    Vec3 towardTarget = lockedTarget.getBoundingBox().getCenter().subtract(fromPoint);
                    if (towardTarget.lengthSqr() > 1.0E-8) {
                        lookVec = towardTarget.normalize();
                    }
                }
            }
            if (hostGroup != null && !useFrozen) {
                hostGroup.freezeLook(lookVec);
            }
            Vec3 center;
            double groundLevel = Double.NEGATIVE_INFINITY;
            if (domainAutomatic) {
                center = automaticContext.origin();
            } else if (mutable && selectionBatch != null && (spaceLock || pathOverride == Trajectory.VORTEX)) {
                center = selectionBatch.crosshairCenter(player);
            } else if (mutable && scatter && !entityLock) {
                center = player.position().add(0.0, player.getBbHeight() * 0.5, 0.0);
                groundLevel = player.getY();
            } else if (spaceLock && selectionBatch != null) {
                center = selectionBatch.resolveAnchor(player);
            } else {
                center = player.getEyePosition();
            }
            long seed = domainAutomatic
                    ? automaticContext.roundSeed() ^ ((long) volley << 16)
                    : player.getUUID().getLeastSignificantBits()
                    ^ player.level().getGameTime()
                    ^ action.getId().hashCode()
                    ^ ((long) volley << 16);
            int geometryIndex = copyIndex;
            int geometryCount = copyCount;
            com.bslx.XueXiMod.shu.technique.release.batch.BirthLayout.Slot birthSlot =
                    com.bslx.XueXiMod.shu.technique.release.batch.BirthLayout.current();
            if (birthSlot != null) {
                geometryIndex = birthSlot.copyOrdinal;
                geometryCount = Math.max(1, birthSlot.spreadCount);
            }
            CastFrame frame = CastFrame.forAttack(usedDamage, applied, tally, geometryIndex, geometryCount,
                    center, lookVec, spaceLock, scatter, entityLock, pathOverride, mutable, seed, groundLevel);
            frame.tracking = tracking;
            frame.radiusMultiplier = bonus.radiusMultiplier;
            frame.releaseInput = frozenInput;
            float ownEnergy = attackDefinition != null ? attackDefinition.energyScale() : 1f;
            frame.energyScale = SkillChainPlan.geometryEnergy(ownEnergy, frozenInput);
            frame.burnSeconds = bonus.burnSeconds;
            frame.seedPoints = bonus.seedPoints;
            frame.controlTicks = bonus.controlTicks;
            frame.extinguish = bonus.extinguish;
            frame.knockback = bonus.knockback;
            frame.speedMultiplier = bonus.speedMultiplier;
            frame.tideSuccess = bonus == null ? TideMarkSuccess.NONE : bonus.tideSuccess(player.getUUID());
            frame.fieldDamageScale = influence.damageScale();
            frame.healAmount = pickedAmount(attackDefinition == null ? 0f : attackDefinition.healAmount(), influence.healAmount);
            frame.healCaster = attackDefinition != null && attackDefinition.healCaster();
            frame.pullStrength = pickedAmount(attackDefinition == null ? 0f : attackDefinition.pullStrength(), influence.pullStrength);
            frame.wetnessGrant = pickedGrant(attackDefinition == null ? 0 : attackDefinition.wetnessGrant(), influence.wetnessGrant);
            if (domainAutomatic && influence.pullAnchor == null) {
                frame.pullAnchor = automaticContext.origin();
            } else {
                frame.pullAnchor = influence.pullAnchor != null ? influence.pullAnchor : player.position();
            }
            frame.blocksMovement = attackDefinition != null && attackDefinition.blocksMovement();
            if ((attackDefinition != null && attackDefinition.purifyOnHit()) || influence.purify) {
                frame.extinguish = true;
            }
            if (attackDefinition != null && attackDefinition.knockbackStrength() > frame.knockback) {
                frame.knockback = attackDefinition.knockbackStrength();
            }
            if (attackDefinition != null) {
                frame.liftStrength = attackDefinition.liftStrength();
            }
            if (heavySession != null) {
                frame.heavyWater = heavySession.heavy();
                frame.releaseGroup = heavySession.groupId();
            }
            if (contactOrigin != null) {
                frame.overrideGeometry = true;
                frame.origin = position;
                frame.anchor = position;
                frame.look = lookVec;
                double flatReach = Math.sqrt(lookVec.x * lookVec.x + lookVec.z * lookVec.z);
                frame.planeNormal = flatReach < 1.0E-4
                        ? new Vec3(0.0, 0.0, 1.0)
                        : new Vec3(lookVec.x / flatReach, 0.0, lookVec.z / flatReach);
                frame.roll = 0.0F;
                frame.pose3d = false;
                frame.adoptSharedAnchor();
            }
            if (domainAutomatic) {
                applyDomainFrame(frame, automaticContext, lookVec);
                int effectTick = player.getServer() == null ? 0 : player.getServer().getTickCount();
                LifetimeToken effectToken = automaticContext.token();
                if (effectToken == null || !effectToken.valid(effectTick)) {
                    return;
                }
            }
            String batchMark = settlementBatch == null
                    ? "loose-" + player.serverLevel().getGameTime()
                    : Integer.toUnsignedString(System.identityHashCode(settlementBatch));
            PartingOffers.present(PartingOperationId.derive(player.getUUID(), batchMark, action.getId(), actionIndex, volley));
            ReleaseBatch.bindActiveOffer(settlementBatch == null ? null : settlementBatch.explicitOffer(actionIndex));
            CastFrame.bind(frame);
            try {
                if (hostGroup != null) {
                    hostGroup.noteCaster(player, frame);
                } else {
                    HitPayloads.applyCaster(player, frame);
                }
                TechniqueCastContext castContext = new TechniqueCastContext(usedDamage, lookVec, position, applied,
                        onFirstTrigger, frameLock, dropThisCast, actionSink);
                effect.execute(player, action, weapon, castContext);
            } finally {
                PartingOffers.clear();
                CastFrame.unbind();
                ReleaseBatch.bindActiveOffer(null);
            }
        } finally {
            boolean holdHeavy = openedGroup != null && heavySession != null;
            if (holdHeavy) {
                openedGroup.keepHeavy(heavySession);
            } else if (heavySession != null && copyIndex >= copyCount - 1) {
                HeavyWater.finish(heavySession);
            }
            if (!holdHeavy) {
                HeavyWater.clearCurrent();
            }
            if (settlementBatch != null) {
                ReleaseBatch.bind(outer);
            }
        }
        } finally {
            PerformanceRecorder.end(PerfMetric.SEGMENT_EXECUTE, segmentStart);
        }
    }

    /**
     * 还没进宿主组的拍号术式，由第 0 份打开自己的父释放并一次提交全部复制。
     * 后一份直接交回，避免各自推进。已经在宿主组里的调用不重复包一层。
     */
    private static boolean commitLooseHost(ServerPlayer player, Technique action, List<Technique> techniques,
                                            int actionIndex, ItemStack weapon, float finalDamage, boolean carries,
                                            EnchantmentResolution enchantments, Consumer<Vec3> onFirstTrigger,
                                            boolean lockThisCast, boolean dropThisCast,
                                            ReleaseBatch.Tally tally, int copyIndex, int copyCount, ReleaseBatch batch,
                                            EnchantBonus bonus, int volley, Vec3 lookVec, Vec3 position, CastSource castSource,
                                            ReleaseInput chainInput, CastPlanContext planContext) {
        ReleaseInput frozenInput = chainInput == null ? ReleaseInput.BASE : chainInput;
        ReleaseDefinition definition = ReleaseRegistry.get(action.getId());
        if (definition == null || !definition.submitsHostGroup() || HostGroupContext.current() != null) {
            return false;
        }
        if (copyIndex > 0) {
            return true;
        }
        if (action.getType() == TechniqueType.SWORD) {
            player.swing(InteractionHand.MAIN_HAND, true);
        }
        HostCast hostCast = HostCast.open(player.getUUID(), castSource);
        hostCast.hold();
        try {
            UUID hostGroup = hostCast.hostId(volley, 0);
            commitHostGroup(player, action, techniques, actionIndex, weapon, finalDamage, carries, enchantments,
                    onFirstTrigger, lockThisCast, dropThisCast, tally, copyCount, batch, bonus, volley, lookVec, position,
                    null, null, hostCast, hostGroup, null, frozenInput, planContext);
        } finally {
            hostCast.release();
        }
        return true;
    }

    /** 领域两条开域路径共用的空间身份。锁定实体不挪原点，垂落不放倒竖轴。 */
    static DomainCastContext domainSpace(ServerPlayer player, List<Technique> techniques, int actionIndex,
                                         UUID groupId, boolean explicitContact, Vec3 contactPoint,
                                         MemberCastView view) {
        if (player == null) {
            throw new IllegalStateException("领域释放缺少施法者");
        }
        RoleScan roles = view == null
                ? scanRoles(techniques, actionIndex)
                : new RoleScan(view.spaceLock, view.entityLock, view.scatter, view.tracking, view.pathOverride);
        boolean dropPath = view != null ? view.drop : roles.pathOverride == Trajectory.DROP;
        return new DomainCastContext(groupId, actionIndex, roles.spaceLock, roles.scatter, roles.entityLock,
                dropPath, explicitContact, contactPoint);
    }

    static RoleScan scanRoles(List<Technique> techniques, int actionIndex) {
        long roleScanStart = PerformanceRecorder.begin();
        try {
            boolean spaceLock = false;
            boolean entityLock = false;
            boolean scatter = false;
            boolean tracking = false;
            Trajectory pathOverride = null;
            for (int earlierIndex = actionIndex - 1; earlierIndex >= 0; earlierIndex--) {
                Technique earlier = techniques.get(earlierIndex);
                if (earlier.getBaseDamage() > 0 && !earlier.isEnchantment()) {
                    if (SkillSegmentMath.sharesDualRelease(techniques, earlierIndex, actionIndex)) {
                        continue;
                    }
                    break;
                }
                switch (SkillSegmentMath.roleOf(earlier)) {
                    case SEEK_SPACE -> spaceLock = true;
                    case SEEK_ENTITY -> entityLock = true;
                    case TRAJECTORY_TRACKING -> tracking = true;
                    case TRAJECTORY_SCATTER -> scatter = true;
                    case TRAJECTORY_DROP -> {
                        if (pathOverride == null) {
                            ReleaseDefinition pathDefinition = ReleaseRegistry.get(earlier.getId());
                            if (pathDefinition != null) {
                                pathOverride = pathDefinition.trajectory();
                            }
                        }
                    }
                    default -> {
                    }
                }
            }
            return new RoleScan(spaceLock, entityLock, scatter, tracking, pathOverride);
        } finally {
            PerformanceRecorder.end(PerfMetric.CHAIN_ROLE_SCAN, roleScanStart);
        }
    }

    private static RoleScan resolveRoles(List<Technique> techniques, int actionIndex, CastPlanContext planContext) {
        MemberCastView boundView = boundMemberView.get();
        if (boundView != null) {
            return new RoleScan(boundView.spaceLock, boundView.entityLock, boundView.scatter,
                    boundView.tracking, boundView.pathOverride);
        }
        if (planContext != null && planContext.canReuseStructure()) {
            RoleScan cached = planContext.roleScan(actionIndex);
            if (cached != null) {
                return cached;
            }
        }
        return scanRoles(techniques, actionIndex);
    }

    static final class RoleScan {
        final boolean spaceLock;
        final boolean entityLock;
        final boolean scatter;
        final boolean tracking;
        final Trajectory pathOverride;

        RoleScan(boolean spaceLock, boolean entityLock, boolean scatter, boolean tracking, Trajectory pathOverride) {
            this.spaceLock = spaceLock;
            this.entityLock = entityLock;
            this.scatter = scatter;
            this.tracking = tracking;
            this.pathOverride = pathOverride;
        }
    }

    /** 术式自己的一份和场地的一份不叠加，取更大的那份。 */
    private static float pickedAmount(float fromDefinition, float fromField) {
        return fromDefinition >= fromField ? fromDefinition : fromField;
    }

    private static int pickedGrant(int fromDefinition, int fromField) {
        return fromDefinition >= fromField ? fromDefinition : fromField;
    }

    private static ReleaseExecutionContext domainContext() {
        ReleaseExecutionContext currentContext = ReleaseExecutionContext.current();
        if (currentContext == null || currentContext.mode() != ReleaseInputMode.DOMAIN_AUTOMATIC) {
            return null;
        }
        return currentContext;
    }

    private static boolean automaticBlocked(ServerPlayer player) {
        ReleaseExecutionContext currentContext = domainContext();
        if (currentContext == null) {
            return false;
        }
        PublicationAttempt attempt = PublicationAttempt.current();
        if (attempt != null && !attempt.allowsPublication()) {
            return true;
        }
        int nowTick = player == null || player.getServer() == null ? 0 : player.getServer().getTickCount();
        LifetimeToken token = currentContext.token();
        return token == null || !token.valid(nowTick);
    }

    /**
     * 规则几何已经写完后，把发射源收回本轮体积。缺原点时垂落只抬一次。
     * 这里的正下方只是生成前的占位，每一发的斜向在生成口覆盖它。
     */
    private static void applyDomainFrame(CastFrame frame, ReleaseExecutionContext automaticContext, Vec3 lookVec) {
        frame.execution = automaticContext;
        boolean missingOrigin = frame.origin == null;
        Vec3 sourceOrigin = missingOrigin ? automaticContext.origin() : frame.origin;
        if (missingOrigin && frame.drop) {
            sourceOrigin = sourceOrigin.add(0.0, 8.0, 0.0);
        }
        Vec3 sourceAnchor = frame.anchor == null ? automaticContext.origin() : frame.anchor;
        frame.origin = automaticContext.volume().clampPoint(sourceOrigin);
        frame.anchor = automaticContext.volume().clampPoint(sourceAnchor);
        frame.overrideGeometry = true;
        if (frame.drop) {
            frame.look = new Vec3(0.0, -1.0, 0.0);
        } else if (frame.look == null) {
            frame.look = lookVec == null ? automaticContext.baseDirection() : lookVec;
        }
    }
}
"}, {"path": "src/main/java/com/bslx/XueXiMod/status/WetnessFlight.java", "sha256": "fbe3b286ea8c593f8343e5315008f6a09263f4196d995c6ace77a7ce6466d7b8", "content": "package com.bslx.XueXiMod.status;

import com.bslx.XueXiMod.shu.technique.release.domain.motion.VolumeMotionRuntime;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.entity.MoverType;
import net.minecraft.world.entity.ambient.Bat;
import net.minecraft.world.entity.boss.EnderDragonPart;
import net.minecraft.world.entity.boss.enderdragon.EnderDragon;
import net.minecraft.world.entity.monster.Vex;
import net.minecraft.world.phys.AABB;
import net.minecraft.world.phys.Vec3;

import java.util.ArrayList;
import java.util.List;
import java.util.WeakHashMap;

/** 三级缓慢下降，四级快速坠落。速度夹紧不改摔伤；恼鬼和末影龙只裁追加的竖直段。 */
public final class WetnessFlight {
    public static final double SLOW_LIMIT = -0.08D;
    public static final double FAST_LIMIT = -0.30D;

    private static final ThreadLocal<LivingEntity> TRAVEL_GUARD = new ThreadLocal<>();
    private static final List<Probe> extraProbes = new ArrayList<>();
    private static final WeakHashMap<EnderDragon, Double> DRAGON_EXTRA = new WeakHashMap<>();

    private WetnessFlight() {}

    /** 实体类本身不能改时，用这个加入飞行判断。不读取免摔伤标签。 */
    public static void register(Probe probe) {
        if (probe != null) {
            extraProbes.add(probe);
        }
    }

    public static double limitedVertical(int tier, double vertical) {
        double ceiling;
        if (tier >= 4) {
            ceiling = FAST_LIMIT;
        } else if (tier == 3) {
            ceiling = SLOW_LIMIT;
        } else {
            return vertical;
        }
        if (vertical > ceiling) {
            return ceiling;
        }
        return vertical;
    }

    /** 相对原竖直速度，潮湿还要再下降的量。已经更快时为 0。 */
    public static double extraDown(int tier, double vanillaVertical) {
        return limitedVertical(tier, vanillaVertical) - vanillaVertical;
    }

    /** 乘客、落地、实际流体不下降。玩家身份和飞行类别不再作为门槛。 */
    public static boolean descentEligible(
            boolean human,
            boolean passenger,
            boolean grounded,
            boolean submerged,
            boolean flyingBody,
            boolean flyingNow,
            boolean explicitFlight) {
        return !passenger && !grounded && !submerged;
    }

    public static boolean isDescentExempt(LivingEntity entity) {
        return WetnessFlightExempt.isExempt(entity);
    }

    public static boolean actualFluid(LivingEntity entity) {
        return entity.isInWater() || entity.isInLava() || entity.isInFluidType();
    }

    public static void beforeTravel(LivingEntity entity) {
        if (entity == null) {
            return;
        }
        LivingEntity active = TRAVEL_GUARD.get();
        if (active == entity) {
            return;
        }
        TRAVEL_GUARD.set(entity);
        try {
            clampDescent(entity);
        } finally {
            TRAVEL_GUARD.set(active);
        }
    }

    public static Vec3 adjustVexMove(LivingEntity entity, MoverType type, Vec3 movement) {
        if (!(entity instanceof Vex) || movement == null || type != MoverType.SELF || entity.isPassenger()) {
            return movement;
        }
        if (VolumeMotionRuntime.hasEffectiveUpdraft(entity)) {
            double rise = VolumeMotionRuntime.riseIntent(entity);
            if (movement.y < rise) {
                return new Vec3(movement.x, rise, movement.z);
            }
            return movement;
        }
        if (!canAddExtra(entity)) {
            return movement;
        }
        double extra = extraDown(WetnessTiers.of(entity).tier(), movement.y);
        if (extra == 0.0D) {
            return movement;
        }
        AABB finished = entity.getBoundingBox().move(movement);
        double allowed = WetnessFlightClip.clipExtra(
                finished,
                extra,
                entity.level().getBlockCollisions(entity, finished.expandTowards(0.0D, extra, 0.0D)));
        if (allowed == 0.0D) {
            return movement;
        }
        return new Vec3(movement.x, movement.y + allowed, movement.z);
    }

    public static void beginDragonStep(EnderDragon dragon) {
        if (dragon == null || dragon.level().isClientSide()) {
            return;
        }
        DRAGON_EXTRA.remove(dragon);
    }

    public static Vec3 adjustDragonMove(EnderDragon dragon, MoverType type, Vec3 movement) {
        if (dragon == null || dragon.level().isClientSide()) {
            return movement;
        }
        if (movement == null) {
            return movement;
        }
        if (VolumeMotionRuntime.hasEffectiveUpdraft(dragon)) {
            DRAGON_EXTRA.put(dragon, 0.0D);
            return movement;
        }
        if (type != MoverType.SELF || !canAddExtra(dragon)) {
            DRAGON_EXTRA.put(dragon, 0.0D);
            return movement;
        }
        double extra = extraDown(WetnessTiers.of(dragon).tier(), movement.y);
        DRAGON_EXTRA.put(dragon, extra);
        return movement;
    }

    public static AABB correctDragonDescent(
            EnderDragon dragon,
            EnderDragonPart head,
            EnderDragonPart neck,
            EnderDragonPart body,
            AABB preparedHead) {
        AABB unchanged = preparedHead;
        if (unchanged == null && head != null) {
            unchanged = head.getBoundingBox();
        }
        if (dragon == null || dragon.level().isClientSide()) {
            return unchanged;
        }
        if (VolumeMotionRuntime.hasEffectiveUpdraft(dragon)) {
            DRAGON_EXTRA.remove(dragon);
            if (head == null) {
                return unchanged;
            }
            return head.getBoundingBox();
        }
        Double stored = DRAGON_EXTRA.remove(dragon);
        if (isDescentExempt(dragon)) {
            return unchanged;
        }
        if (stored == null || stored >= 0.0D) {
            return unchanged;
        }
        double extra = stored;
        double allowedHead = clipDragonPart(dragon, head, extra);
        double allowedNeck = clipDragonPart(dragon, neck, extra);
        double allowedBody = clipDragonPart(dragon, body, extra);
        double allowed = WetnessFlightClip.strictestExtra(extra, allowedHead, allowedNeck, allowedBody);
        if (allowed == 0.0D) {
            return unchanged;
        }
        addVertical(dragon, allowed);
        EnderDragonPart[] parts = dragon.getSubEntities();
        if (parts != null) {
            for (EnderDragonPart part : parts) {
                if (part != null) {
                    addVertical(part, allowed);
                }
            }
        }
        if (head == null) {
            return unchanged;
        }
        return head.getBoundingBox();
    }

    private static void clampDescent(LivingEntity entity) {
        if (entity.level().isClientSide() || entity instanceof Vex || entity instanceof EnderDragon) {
            return;
        }
        if (VolumeMotionRuntime.hasEffectiveUpdraft(entity)) {
            return;
        }
        if (entity instanceof Bat bat && bat.isResting()) {
            return;
        }
        if (!entity.isAlive() || isDescentExempt(entity)) {
            return;
        }
        if (!descentEligible(
                false,
                entity.isPassenger(),
                entity.onGround(),
                actualFluid(entity),
                false,
                false,
                false)) {
            return;
        }
        int tier = WetnessTiers.of(entity).tier();
        if (tier < 3) {
            return;
        }
        Vec3 motion = entity.getDeltaMovement();
        double nextVertical = limitedVertical(tier, motion.y);
        if (nextVertical == motion.y) {
            return;
        }
        entity.setDeltaMovement(motion.x, nextVertical, motion.z);
    }

    private static boolean canAddExtra(LivingEntity entity) {
        return entity != null
                && !entity.level().isClientSide()
                && !isDescentExempt(entity)
                && !entity.isPassenger()
                && !actualFluid(entity);
    }

    private static double clipDragonPart(EnderDragon dragon, EnderDragonPart part, double extra) {
        if (part == null || dragon.level() == null) {
            return 0.0D;
        }
        AABB current = part.getBoundingBox();
        AABB swept = current.expandTowards(0.0D, extra, 0.0D);
        return WetnessFlightClip.clipExtra(current, extra, WetnessFlightClip.dragonObstacles(dragon.level(), dragon, swept));
    }

    private static void addVertical(LivingEntity dragon, double allowed) {
        dragon.setPos(dragon.getX(), dragon.getY() + allowed, dragon.getZ());
    }

    private static void addVertical(EnderDragonPart part, double allowed) {
        part.setPos(part.getX(), part.getY() + allowed, part.getZ());
    }

    @FunctionalInterface
    public interface Probe {
        boolean affected(LivingEntity entity);
    }
}
"}, {"path": "src/main/java/com/bslx/XueXiMod/status/WetnessState.java", "sha256": "84a6a511a9b6556717681baf2d819ad9d5d29ca1a73e11eaaecb9ea919fed77a", "content": "package com.bslx.XueXiMod.status;

import com.bslx.XueXiMod.registry.ModMobEffects;
import net.minecraft.world.effect.MobEffect;
import net.minecraft.world.effect.MobEffectInstance;
import net.minecraft.world.entity.LivingEntity;

/** 潮湿。0 到 100，四档，每次成功施加都刷新 50 秒。只能由术式调用 {@link #grant}。 */
public final class WetnessState {
    public static final AttributeStateDefinition DEFINITION = new AttributeStateDefinition("wetness", 100);
    public static final int DURATION_TICKS = 1000;

    private WetnessState() {}

    public static int tierOf(int amount) {
        if (amount <= 0) {
            return 0;
        }
        if (amount <= 25) {
            return 1;
        }
        if (amount <= 50) {
            return 2;
        }
        if (amount <= 75) {
            return 3;
        }
        return 4;
    }

    public static int read(LivingEntity target) {
        return AttributeStateService.read(target, DEFINITION);
    }

    public static void grant(LivingEntity target, int added) {
        if (target == null || !target.isAlive() || added <= 0 || target.level().isClientSide()) {
            return;
        }
        int current = read(target);
        int updated = current + added;
        if (updated > DEFINITION.upperBound()) {
            updated = DEFINITION.upperBound();
        }
        AttributeStateService.write(target, DEFINITION, updated);
        int tier = tierOf(updated);
        MobEffect effect = ModMobEffects.WETNESS.get();
        target.addEffect(new MobEffectInstance(effect, DURATION_TICKS, tier - 1, false, true, true));
    }

    public static void reconcile(LivingEntity target) {
        int stored = read(target);
        AttributeStateService.reconcile(target, DEFINITION, ModMobEffects.WETNESS.get(), tierOf(stored));
    }

    public static int remainingDuration(LivingEntity target) {
        if (target == null) {
            return 0;
        }
        MobEffectInstance instance = target.getEffect(ModMobEffects.WETNESS.get());
        if (instance == null) {
            return 0;
        }
        return instance.getDuration();
    }

    /** 按调用方给出的剩余时间改精确湿度。不走 {@link #grant}，因此不会把计时刷回 1000。 */
    public static void replaceExact(LivingEntity target, int amount, int durationTicks) {
        if (target == null || target.level() == null || target.level().isClientSide()) {
            return;
        }
        MobEffect effect = ModMobEffects.WETNESS.get();
        if (amount <= 0 || durationTicks <= 0) {
            clear(target);
            return;
        }
        int amplifier = tierOf(amount) - 1;
        if (amplifier < 0) {
            amplifier = 0;
        }
        AttributeStateService.replace(target, DEFINITION, effect, amount, durationTicks, amplifier);
    }

    /** 按剩余时间改精确湿度。不走 {@link #grant}，因此不会把计时刷回 1000。 */
    public static void replacePreservingDuration(LivingEntity target, int amount) {
        if (target == null || target.level().isClientSide()) {
            return;
        }
        MobEffect effect = ModMobEffects.WETNESS.get();
        int durationTicks = remainingDuration(target);
        if (amount <= 0 || durationTicks <= 0) {
            clear(target);
            return;
        }
        int amplifier = tierOf(amount) - 1;
        if (amplifier < 0) {
            amplifier = 0;
        }
        AttributeStateService.replace(target, DEFINITION, effect, amount, durationTicks, amplifier);
    }

    public static void clear(LivingEntity target) {
        if (target == null || target.level().isClientSide()) {
            return;
        }
        AttributeStateService.clear(target, DEFINITION, ModMobEffects.WETNESS.get());
    }
}
"}, {"path": "src/main/java/com/bslx/XueXiMod/shu/technique/release/domain/DomainInstance.java", "sha256": "7095049e4e17a065a8f316fd7ee8b7d0defcfab12f3f13a9df8b0d3286a83a32", "content": "package com.bslx.XueXiMod.shu.technique.release.domain;

import com.bslx.XueXiMod.shu.technique.enchant.EnchantmentSnapshot;
import com.bslx.XueXiMod.shu.technique.release.ReleaseInput;
import com.bslx.XueXiMod.shu.technique.release.domain.motion.StillWaterLease;
import com.bslx.XueXiMod.shu.technique.release.domain.motion.VolumeMotionRuntime;
import com.bslx.XueXiMod.shu.technique.release.bind.BoundReleasePlan;
import com.bslx.XueXiMod.shu.technique.release.bind.RoundHandle;
import com.bslx.XueXiMod.shu.technique.release.contact.ContactCarrier;
import com.bslx.XueXiMod.shu.technique.release.contact.ContactEnchantState;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.phys.AABB;

import javax.annotation.Nullable;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.UUID;

/** 一个已经落下的领域。几何固定，供给不写成玩家身上的永久状态。 */
public final class DomainInstance implements ContactCarrier, DomainBound, HostView {
    private final UUID instanceId = UUID.randomUUID();
    private final UUID ownerId;
    private final ServerLevel level;
    private DomainGeometry geometry;
    private final DomainDefinition definition;
    private final int revision = 1;
    private final int startedAt;
    private final int expiresAt;
    private final long visualOrigin;
    private final long visualEnd;
    private final int animSeed;
    private final @Nullable BoundReleasePlan boundPlan;
    private UUID releaseGroup;
    private int declarationSlot = -1;
    private UUID mountedProvider;
    private UUID mountedHost;
    private boolean mountRetired;
    private boolean liftedColumn;
    private double columnScale = -1.0D;
    private final ArrayList<UUID> publishedRoots = new ArrayList<>();
    private final ArrayList<RoundHandle> openRounds = new ArrayList<>();
    private int nextBindingBeat;
    private boolean active = true;
    private boolean removalBroadcast;
    private ContactEnchantState contact;

    DomainInstance(UUID ownerId, ServerLevel level, DomainGeometry geometry, DomainDefinition definition, int startedAt,
                   int scaledLife) {
        this(ownerId, level, geometry, definition, startedAt, scaledLife, null);
    }

    DomainInstance(UUID ownerId, ServerLevel level, DomainGeometry geometry, DomainDefinition definition, int startedAt,
                   int scaledLife, @Nullable BoundReleasePlan boundPlan) {
        this.ownerId = ownerId;
        this.level = level;
        this.geometry = geometry;
        this.definition = definition;
        this.startedAt = startedAt;
        this.visualOrigin = level.getGameTime();
        FrozenClock clock = FrozenClock.freeze(startedAt, this.visualOrigin, scaledLife);
        this.expiresAt = clock.expiresAt;
        this.visualEnd = clock.visualEnd;
        this.animSeed = Math.floorMod(instanceId.hashCode(), 16);
        this.boundPlan = boundPlan;
        this.nextBindingBeat = boundPlan == null ? 0 : startedAt + DomainBindingRuntime.PERIOD_TICKS;
    }

    /** 同一份已缩放寿命同时写下服务器到期刻和视觉结束时刻。非正寿命不进到期助手。 */
    public static final class FrozenClock {
        public final int expiresAt;
        public final long visualEnd;

        private FrozenClock(int expiresAt, long visualEnd) {
            this.expiresAt = expiresAt;
            this.visualEnd = visualEnd;
        }

        public static FrozenClock freeze(int startedAt, long origin, int scaledLife) {
            if (scaledLife <= 0) {
                return new FrozenClock(startedAt + scaledLife, origin + scaledLife);
            }
            return new FrozenClock(
                    ReleaseInput.expiryTick(startedAt, scaledLife),
                    ReleaseInput.expiryGameTime(origin, scaledLife));
        }
    }

    void bindContact(EnchantmentSnapshot snapshot) {
        if (snapshot == null) {
            return;
        }
        this.contact = ContactEnchantState.open(this, snapshot);
    }

    void close() {
        if (!active) {
            return;
        }
        active = false;
        try {
            cancelOpenRounds();
        } finally {
            VolumeMotionRuntime.onClose(this);
            StillWaterLease.release(this);
            NetherDomainCycle.drop(this.instanceId);
            if (contact != null) {
                contact.close();
                contact = null;
            }
        }
    }

    /** 开域时冻结的绑定计划。没有绑定时为空。同一波多份实例共用这一份不可变计划。 */
    @Nullable
    public BoundReleasePlan boundPlan() {
        return boundPlan;
    }

    @Override
    public int nextBindingBeat() {
        return nextBindingBeat;
    }

    @Override
    public void advanceBindingBeat(int followingBeat) {
        this.nextBindingBeat = followingBeat;
    }

    /**
     * 执行返回后还能不能把新句柄留在本实例上。
     * 领域仍开启、未到到期刻，主人在线、存活，并且仍在宿主维度。
     */
    @Override
    public boolean roundStillHosted(int now) {
        if (!active || level == null || ownerId == null) {
            return false;
        }
        if (ReleaseInput.hasExpired(now, expiresAt)) {
            return false;
        }
        MinecraftServer server = level.getServer();
        if (server == null) {
            return false;
        }
        ServerPlayer owner = server.getPlayerList().getPlayer(ownerId);
        return owner != null && owner.isAlive() && owner.level() == level;
    }

    @Override
    public void trackRound(RoundHandle handle, int now) {
        if (handle == null) {
            return;
        }
        if (!roundStillHosted(now)) {
            if (!handle.done()) {
                handle.cancel();
            }
            return;
        }
        if (handle.done()) {
            return;
        }
        openRounds.add(handle);
    }

    @Override
    public void sweepFinishedRounds() {
        openRounds.removeIf(RoundHandle::done);
    }

    @Override
    public void cancelOpenRounds() {
        if (openRounds.isEmpty()) {
            return;
        }
        ArrayList<RoundHandle> pendingRounds = new ArrayList<>(openRounds);
        openRounds.clear();
        Throwable failure = null;
        for (RoundHandle handle : pendingRounds) {
            if (handle == null || handle.done()) {
                continue;
            }
            try {
                handle.cancel();
            } catch (Throwable thrown) {
                if (failure == null) {
                    failure = thrown;
                }
            }
        }
        if (failure instanceof RuntimeException runtimeFailure) {
            throw runtimeFailure;
        }
        if (failure instanceof Error errorFailure) {
            throw errorFailure;
        }
        if (failure != null) {
            throw new IllegalStateException(failure);
        }
    }

    boolean markRemovalBroadcast() {
        if (removalBroadcast) {
            return false;
        }
        removalBroadcast = true;
        return true;
    }

    public UUID instanceId() {
        return instanceId;
    }

    public DomainGeometry geometry() {
        return geometry;
    }

    public void adoptGeometry(DomainGeometry next) {
        if (next != null) {
            this.geometry = next;
        }
    }

    public void bindRelease(UUID group, int slot) {
        this.releaseGroup = group;
        this.declarationSlot = slot;
    }

    public UUID releaseGroup() {
        return releaseGroup;
    }

    public int declarationSlot() {
        return declarationSlot;
    }

    public UUID mountedProvider() {
        return mountedProvider;
    }

    public void setMountedProvider(UUID providerId) {
        this.mountedProvider = providerId;
    }

    public UUID mountedHost() {
        return mountedHost;
    }

    public void setMountedHost(UUID hostId) {
        this.mountedHost = hostId;
    }

    public void clearMount() {
        this.mountedProvider = null;
        this.mountedHost = null;
    }

    public void clearProvider() {
        this.mountedProvider = null;
    }

    public void retireMount() {
        this.mountRetired = true;
        this.mountedHost = null;
    }

    public boolean mountRetired() {
        return mountRetired;
    }

    public boolean liftedColumn() {
        return liftedColumn;
    }

    public void setLiftedColumn(boolean lifted) {
        this.liftedColumn = lifted;
    }

    public List<UUID> publishedRoots() {
        return List.copyOf(publishedRoots);
    }

    public boolean replacePublishedRoots(List<UUID> next) {
        ArrayList<UUID> incoming = new ArrayList<>();
        if (next != null) {
            for (UUID entityId : next) {
                if (entityId != null && !incoming.contains(entityId)) {
                    incoming.add(entityId);
                }
            }
        }
        incoming.sort(Comparator.naturalOrder());
        if (incoming.equals(publishedRoots)) {
            return false;
        }
        publishedRoots.clear();
        publishedRoots.addAll(incoming);
        return true;
    }

    public double captureColumnScale(double dryHeight, double currentHeight) {
        if (columnScale < 0.0D) {
            columnScale = dryHeight <= 1.0E-4D ? 1.0D : currentHeight / dryHeight;
        }
        return columnScale;
    }

    public DomainDefinition definition() {
        return definition;
    }

    public int startedAt() {
        return startedAt;
    }

    public int expiresAt() {
        return expiresAt;
    }

    public float auraDamage() {
        return definition.auraSpec() == null ? 0f : definition.auraSpec().bonusDamage();
    }

    @Override
    public UUID hostId() {
        return instanceId;
    }

    @Override
    public int revision() {
        return revision;
    }

    @Override
    public DomainBoundary boundary() {
        return definition.boundary();
    }

    public DomainVisual visual() {
        return definition.visual();
    }

    public long visualOrigin() {
        return visualOrigin;
    }

    public long visualEnd() {
        return visualEnd;
    }

    public int animSeed() {
        return animSeed;
    }

    @Override
    public UUID ownerId() {
        return ownerId;
    }

    @Override
    public boolean active() {
        return active;
    }

    @Override
    public boolean touches(LivingEntity target) {
        return target != null && geometry.intersects(target.getBoundingBox());
    }

    @Override
    public ServerLevel hostLevel() {
        return level;
    }

    @Override
    public AABB queryBox() {
        return geometry.bounds().inflate(1.0);
    }
}
"}, {"path": "src/main/java/com/bslx/XueXiMod/shu/technique/release/multicast/MulticastExpansion.java", "sha256": "9e969a62c6e979c76a16509ee6111d103fd1eb60176b11d0d07d8a3a8322dbcd", "content": "package com.bslx.XueXiMod.shu.technique.release.multicast;

import java.util.List;
import java.util.Objects;

/**
 * 一次多重的不可变展开。全项目只用 {@link MulticastParser} 产生它。
 * 下标都是原始装配顺序，不是 {@code TechniqueChain.split} 之后的段号。
 */
public final class MulticastExpansion {
    /** 多重队列里，后一个实际成员比前一个晚的刻数。第 0 个成员不延迟。 */
    public static final int MEMBER_GAP_TICKS = 3;

    private final boolean applicable;
    private final boolean releases;
    private final int startIndex;
    private final int nextIndex;
    private final List<Integer> consumedIndexes;
    private final List<Integer> chargedIndexes;
    private final List<MulticastIgnore> ignoredSlots;
    private final List<MulticastMember> orderedMembers;
    private final List<Integer> inheritedModifierIndexes;

    MulticastExpansion(boolean applicable, boolean releases, int startIndex, int nextIndex,
                       List<Integer> consumedIndexes, List<Integer> chargedIndexes,
                       List<MulticastIgnore> ignoredSlots, List<MulticastMember> orderedMembers,
                       List<Integer> inheritedModifierIndexes) {
        this.applicable = applicable;
        this.releases = releases;
        this.startIndex = startIndex;
        this.nextIndex = nextIndex;
        this.consumedIndexes = List.copyOf(consumedIndexes);
        this.chargedIndexes = List.copyOf(chargedIndexes);
        this.ignoredSlots = List.copyOf(ignoredSlots);
        this.orderedMembers = List.copyOf(orderedMembers);
        this.inheritedModifierIndexes = List.copyOf(inheritedModifierIndexes);
    }

    static MulticastExpansion notApplicable(int startIndex) {
        return new MulticastExpansion(false, false, startIndex, startIndex,
                List.of(), List.of(), List.of(), List.of(), List.of());
    }

    /** 根下标不是多重声明时为假。调用者保持原来的单段路径。 */
    public boolean applicable() {
        return applicable;
    }

    /** 至少有一个实际执行成员。假表示空展开，付款前失败。 */
    public boolean releases() {
        return releases;
    }

    /** 根多重所在的原始下标。 */
    public int startIndex() {
        return startIndex;
    }

    /** 展开没有读到的下一格。空展开只供查看，调用者不得据此推进游标。 */
    public int nextIndex() {
        return nextIndex;
    }

    /** 本次读过的原始下标，升序，含根多重、前缀和内层。 */
    public List<Integer> consumedIndexes() {
        return consumedIndexes;
    }

    /** 可以各计一次费用和冷却的原始下标，升序。空展开为空。 */
    public List<Integer> chargedIndexes() {
        return chargedIndexes;
    }

    /** 读过但不计费、不进冷却、也不再后附的格。 */
    public List<MulticastIgnore> ignoredSlots() {
        return ignoredSlots;
    }

    /** 实际执行队列。修饰不是成员。复制份不拆成多个成员。 */
    public List<MulticastMember> orderedMembers() {
        return orderedMembers;
    }

    /**
     * 根多重之前、作用于整段展开的索敌、弹道和增幅下标，从前到后。
     * 正伤成员各自持有同一份，不按嵌套层重复。
     */
    public List<Integer> inheritedModifierIndexes() {
        return inheritedModifierIndexes;
    }

    /** 该序号成员相对出手时刻的延迟。0 以及更小的序号立即执行。 */
    public int gapTicks(int memberOrdinal) {
        if (memberOrdinal <= 0) {
            return 0;
        }
        long delayedTicks = (long) memberOrdinal * MEMBER_GAP_TICKS;
        if (delayedTicks > Integer.MAX_VALUE) {
            return Integer.MAX_VALUE;
        }
        return (int) delayedTicks;
    }

    @Override
    public boolean equals(Object other) {
        if (this == other) {
            return true;
        }
        if (!(other instanceof MulticastExpansion)) {
            return false;
        }
        MulticastExpansion expansion = (MulticastExpansion) other;
        return applicable == expansion.applicable
                && releases == expansion.releases
                && startIndex == expansion.startIndex
                && nextIndex == expansion.nextIndex
                && consumedIndexes.equals(expansion.consumedIndexes)
                && chargedIndexes.equals(expansion.chargedIndexes)
                && ignoredSlots.equals(expansion.ignoredSlots)
                && orderedMembers.equals(expansion.orderedMembers)
                && inheritedModifierIndexes.equals(expansion.inheritedModifierIndexes);
    }

    @Override
    public int hashCode() {
        return Objects.hash(applicable, releases, startIndex, nextIndex, consumedIndexes, chargedIndexes,
                ignoredSlots, orderedMembers, inheritedModifierIndexes);
    }
}
